-- ════════ supabase-migrations/004_user_coins.sql ════════
-- Run this in Supabase Dashboard > SQL Editor.
--
-- Moves the coin balance and badge-claim ledger server-side. Client-side
-- state in localStorage was editable by anyone, so paid coin packs and
-- earned-badge rewards were free for the taking.

-- ── user_coins ──────────────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS user_coins (
  user_id    UUID PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE,
  balance    INTEGER NOT NULL DEFAULT 0 CHECK (balance >= 0),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

ALTER TABLE user_coins ENABLE ROW LEVEL SECURITY;

-- Users can read their own balance via the anon key if we ever switch to
-- direct PostgREST reads. Writes always go through server-only RPCs below.
DROP POLICY IF EXISTS "Users can read own coin balance" ON user_coins;
CREATE POLICY "Users can read own coin balance"
  ON user_coins FOR SELECT
  USING (auth.uid() = user_id);

-- ── user_badges ─────────────────────────────────────────────────────────────
-- Ledger of which badges a user has claimed coins for. Primary key prevents
-- double-claiming even if two requests race.
CREATE TABLE IF NOT EXISTS user_badges (
  user_id    UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  badge_id   TEXT NOT NULL,
  earned_at  TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  PRIMARY KEY (user_id, badge_id)
);

ALTER TABLE user_badges ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Users can read own badges" ON user_badges;
CREATE POLICY "Users can read own badges"
  ON user_badges FOR SELECT
  USING (auth.uid() = user_id);

-- ── RPC: add_coins (server-only, called from Stripe webhook) ────────────────
CREATE OR REPLACE FUNCTION add_coins(p_user_id UUID, p_amount INT)
RETURNS INTEGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  new_balance INTEGER;
BEGIN
  IF p_amount <= 0 THEN
    RAISE EXCEPTION 'amount must be positive';
  END IF;

  INSERT INTO user_coins (user_id, balance, updated_at)
  VALUES (p_user_id, p_amount, NOW())
  ON CONFLICT (user_id) DO UPDATE
    SET balance = user_coins.balance + EXCLUDED.balance,
        updated_at = NOW()
  RETURNING balance INTO new_balance;

  RETURN new_balance;
END;
$$;

-- Only the service role (webhook, admin) should add coins. Revoke from the
-- default PUBLIC grant and from the Supabase role aliases.
REVOKE ALL ON FUNCTION add_coins(UUID, INT) FROM PUBLIC;
REVOKE ALL ON FUNCTION add_coins(UUID, INT) FROM anon, authenticated;

-- ── RPC: spend_coins (called by the authed /api/spend-coins endpoint) ──────
-- Returns the new balance, or NULL if the user doesn't have enough.
CREATE OR REPLACE FUNCTION spend_coins(p_user_id UUID, p_amount INT)
RETURNS INTEGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  new_balance INTEGER;
BEGIN
  IF p_amount <= 0 THEN
    RAISE EXCEPTION 'amount must be positive';
  END IF;

  UPDATE user_coins
  SET balance = balance - p_amount,
      updated_at = NOW()
  WHERE user_id = p_user_id
    AND balance >= p_amount
  RETURNING balance INTO new_balance;

  RETURN new_balance; -- NULL when the row was missing or balance insufficient
END;
$$;

REVOKE ALL ON FUNCTION spend_coins(UUID, INT) FROM PUBLIC;
REVOKE ALL ON FUNCTION spend_coins(UUID, INT) FROM anon, authenticated;

-- ── RPC: claim_badge (server-only, called by /api/claim-badge) ─────────────
-- Credits badge coins exactly once. Returns the new balance, or NULL if the
-- badge was already claimed.
CREATE OR REPLACE FUNCTION claim_badge(p_user_id UUID, p_badge_id TEXT, p_coins INT)
RETURNS INTEGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  inserted BOOLEAN := FALSE;
  new_balance INTEGER;
BEGIN
  INSERT INTO user_badges (user_id, badge_id)
  VALUES (p_user_id, p_badge_id)
  ON CONFLICT DO NOTHING;

  GET DIAGNOSTICS inserted = ROW_COUNT;

  IF NOT inserted THEN
    RETURN NULL;
  END IF;

  IF p_coins > 0 THEN
    INSERT INTO user_coins (user_id, balance, updated_at)
    VALUES (p_user_id, p_coins, NOW())
    ON CONFLICT (user_id) DO UPDATE
      SET balance = user_coins.balance + EXCLUDED.balance,
          updated_at = NOW()
    RETURNING balance INTO new_balance;
  ELSE
    SELECT balance INTO new_balance FROM user_coins WHERE user_id = p_user_id;
    IF new_balance IS NULL THEN new_balance := 0; END IF;
  END IF;

  RETURN new_balance;
END;
$$;

REVOKE ALL ON FUNCTION claim_badge(UUID, TEXT, INT) FROM PUBLIC;
REVOKE ALL ON FUNCTION claim_badge(UUID, TEXT, INT) FROM anon, authenticated;


-- ════════ supabase-migrations/005_print_orders.sql ════════
-- supabase-migrations/005_print_orders.sql
-- Run in Supabase SQL editor. Idempotent (uses IF NOT EXISTS / CREATE OR REPLACE).

create table if not exists print_orders (
  id                       uuid primary key default gen_random_uuid(),
  user_id                  uuid not null references auth.users(id) on delete cascade,
  book_id                  text not null,
  book_snapshot            jsonb not null,
  format                   text not null check (format in ('hardcover','softcover')),
  quantity                 int  not null default 1 check (quantity between 1 and 10),
  unit_price_cents         int  not null check (unit_price_cents >= 0),
  shipping_cents           int  not null check (shipping_cents >= 0),
  tax_cents                int  not null default 0 check (tax_cents >= 0),
  total_cents              int  not null check (total_cents >= 0),

  ship_name                text not null,
  ship_address_line1       text not null,
  ship_address_line2       text,
  ship_city                text not null,
  ship_state               text not null,
  ship_postal_code         text not null,
  ship_country             text not null default 'US',
  ship_email               text not null,
  ship_phone               text,

  stripe_payment_intent_id text unique,
  stripe_charge_id         text,

  lulu_order_id            text unique,
  lulu_tracking_url        text,
  lulu_carrier             text,
  lulu_tracking_number     text,

  interior_pdf_url         text,
  cover_pdf_url            text,

  status                   text not null default 'pending'
                           check (status in ('pending','paid','pdf_ready','submitted','in_production','shipped','delivered','failed','refunded')),
  status_message           text,
  created_at               timestamptz default now(),
  updated_at               timestamptz default now()
);

create index if not exists idx_print_orders_user
  on print_orders(user_id, created_at desc);

create index if not exists idx_print_orders_active
  on print_orders(status)
  where status in ('paid','pdf_ready','submitted','in_production','shipped');

-- Auto-bump updated_at
create or replace function set_updated_at_now() returns trigger as $$
begin
  new.updated_at = now();
  return new;
end;
$$ language plpgsql;

drop trigger if exists trg_print_orders_updated_at on print_orders;
create trigger trg_print_orders_updated_at
  before update on print_orders
  for each row execute function set_updated_at_now();

-- RLS: server-side only via service role; client-side cannot write, but can read own rows.
alter table print_orders enable row level security;

drop policy if exists "Users read own print orders" on print_orders;
create policy "Users read own print orders"
  on print_orders for select
  using (auth.uid() = user_id);


-- ════════ supabase-migrations/006_print_pdfs_storage.sql ════════
-- supabase-migrations/006_print_pdfs_storage.sql

-- Create the bucket (private — signed URLs only).
insert into storage.buckets (id, name, public)
values ('print-pdfs', 'print-pdfs', false)
on conflict (id) do nothing;

-- Service role can do anything; clients cannot list, read, or write.
-- We sign URLs server-side and only Lulu fetches them.
drop policy if exists "Service role full access print-pdfs" on storage.objects;
create policy "Service role full access print-pdfs"
  on storage.objects for all
  using (bucket_id = 'print-pdfs' and auth.role() = 'service_role');


-- ════════ supabase-migrations/007_usage_log.sql ════════
-- supabase-migrations/007_usage_log.sql
-- Records every paid AI provider call so the owner can audit costs without
-- depending on provider admin APIs (which often require admin-level keys
-- separate from the regular API key the app uses).

create table if not exists usage_log (
  id              bigserial primary key,
  user_id         uuid references auth.users(id) on delete set null,
  service         text not null check (service in ('anthropic', 'together')),
  feature         text not null,            -- 'story_buddy' / 'generate_image' / 'generate_avatar' / 'pdf_upscale'
  model           text not null,            -- e.g. 'claude-haiku-4-5-20251001', 'FLUX.1-schnell'
  input_tokens    int,                      -- null for image endpoints
  output_tokens   int,                      -- null for image endpoints
  images          int,                      -- null for chat endpoints
  cost_cents      int not null default 0,   -- our estimate in USD cents (uses hardcoded rates; treat as approximate)
  created_at      timestamptz not null default now()
);

create index if not exists idx_usage_log_created_at
  on usage_log(created_at desc);

create index if not exists idx_usage_log_service_created
  on usage_log(service, created_at desc);

create index if not exists idx_usage_log_user_created
  on usage_log(user_id, created_at desc);

-- Service-role only (writes happen from API endpoints with service key).
-- No client-side reads — owner-only reads go through /api/admin/usage which
-- itself service-role queries with an owner-uuid auth check.
alter table usage_log enable row level security;


-- ════════ supabase-migrations/008_webhook_idempotency.sql ════════
-- Run this in Supabase Dashboard > SQL Editor.
--
-- Makes coin-credit webhooks idempotent. Stripe and RevenueCat both use
-- at-least-once delivery and retry on any non-2xx/timeout response, so
-- without a per-event ledger a single purchase could be credited two or
-- more times (e.g. a 500-coin pack becomes 1000). This mirrors the once-only
-- ledger pattern already used by claim_badge in 004.

-- ── processed_webhook_events ────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS processed_webhook_events (
  event_id   TEXT PRIMARY KEY,
  provider   TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

ALTER TABLE processed_webhook_events ENABLE ROW LEVEL SECURITY;
-- No policies: only the service role (webhooks / the RPC below) touches it.

-- ── RPC: credit_coins_once ──────────────────────────────────────────────────
-- Credits coins exactly once per provider event id. Returns the resulting
-- balance (unchanged when the event was already processed).
CREATE OR REPLACE FUNCTION credit_coins_once(
  p_user_id  UUID,
  p_amount   INT,
  p_event_id TEXT,
  p_provider TEXT DEFAULT NULL
)
RETURNS INTEGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  inserted    BOOLEAN := FALSE;
  new_balance INTEGER;
BEGIN
  IF p_amount IS NULL OR p_amount <= 0 THEN
    RAISE EXCEPTION 'amount must be positive';
  END IF;
  IF p_event_id IS NULL OR length(p_event_id) = 0 THEN
    RAISE EXCEPTION 'event id required';
  END IF;

  -- Claim the event id. A conflict means this is a redelivery.
  INSERT INTO processed_webhook_events (event_id, provider)
  VALUES (p_event_id, p_provider)
  ON CONFLICT (event_id) DO NOTHING;

  GET DIAGNOSTICS inserted = ROW_COUNT;

  IF NOT inserted THEN
    SELECT balance INTO new_balance FROM user_coins WHERE user_id = p_user_id;
    RETURN COALESCE(new_balance, 0);
  END IF;

  INSERT INTO user_coins (user_id, balance, updated_at)
  VALUES (p_user_id, p_amount, NOW())
  ON CONFLICT (user_id) DO UPDATE
    SET balance = user_coins.balance + EXCLUDED.balance,
        updated_at = NOW()
  RETURNING balance INTO new_balance;

  RETURN new_balance;
END;
$$;

REVOKE ALL ON FUNCTION credit_coins_once(UUID, INT, TEXT, TEXT) FROM PUBLIC;
REVOKE ALL ON FUNCTION credit_coins_once(UUID, INT, TEXT, TEXT) FROM anon, authenticated;


-- ════════ supabase-migrations/009_daily_generation_cap.sql ════════
-- Run this in Supabase Dashboard > SQL Editor.
--
-- Per-user, per-day hard ceiling on paid image generations. Sits behind the
-- auth + hourly rate limiter as a defense against a single compromised
-- account draining Together/Anthropic credits over a day.

CREATE TABLE IF NOT EXISTS daily_generation_counts (
  user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  day     DATE NOT NULL DEFAULT CURRENT_DATE,
  count   INTEGER NOT NULL DEFAULT 0,
  PRIMARY KEY (user_id, day)
);

ALTER TABLE daily_generation_counts ENABLE ROW LEVEL SECURITY;
-- No policies: only the service role (via the RPC below) touches it.

-- Atomically increment today's count for the user and report whether the
-- request is within the limit. Over-limit attempts still increment, so they
-- stay blocked for the rest of the day.
CREATE OR REPLACE FUNCTION bump_generation(p_user_id UUID, p_limit INT)
RETURNS BOOLEAN
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  new_count INTEGER;
BEGIN
  INSERT INTO daily_generation_counts (user_id, day, count)
  VALUES (p_user_id, CURRENT_DATE, 1)
  ON CONFLICT (user_id, day) DO UPDATE
    SET count = daily_generation_counts.count + 1
  RETURNING count INTO new_count;

  RETURN new_count <= p_limit;
END;
$$;

REVOKE ALL ON FUNCTION bump_generation(UUID, INT) FROM PUBLIC;
REVOKE ALL ON FUNCTION bump_generation(UUID, INT) FROM anon, authenticated;


