-- ════════ supabase-migrations/012_user_streaks.sql ════════
-- Run this in Supabase Dashboard > SQL Editor.
--
-- Daily writing streaks. A "writing day" is any day the kid edits or
-- saves a book; the client reports its LOCAL calendar date and the
-- /api/streak endpoint + this RPC accept it only within ±1 day of UTC
-- today (timezone tolerance without letting anyone fast-forward).

CREATE TABLE IF NOT EXISTS user_streaks (
  user_id          UUID PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE,
  current_streak   INTEGER NOT NULL DEFAULT 0,
  longest_streak   INTEGER NOT NULL DEFAULT 0,
  last_active_date DATE,
  updated_at       TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

ALTER TABLE user_streaks ENABLE ROW LEVEL SECURITY;

-- Users may read their own streak directly (e.g. via the Supabase SDK);
-- writes only happen through the server-only RPC below.
DROP POLICY IF EXISTS "Users can read own streak" ON user_streaks;
CREATE POLICY "Users can read own streak"
  ON user_streaks FOR SELECT
  USING (auth.uid() = user_id);

-- ── RPC: touch_streak (server-only, called by /api/streak) ─────────────────
-- Marks p_day as active for the user and returns the updated streak.
--   same day again          → no-op
--   day after last active   → streak + 1
--   gap (or first ever day) → streak resets to 1
--   day before last active  → no-op (timezone stragglers can't rewind)
CREATE OR REPLACE FUNCTION touch_streak(p_user_id UUID, p_day DATE)
RETURNS TABLE(current_streak INTEGER, longest_streak INTEGER, last_active_date DATE)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  cur user_streaks%ROWTYPE;
BEGIN
  IF p_day < CURRENT_DATE - 1 OR p_day > CURRENT_DATE + 1 THEN
    RAISE EXCEPTION 'day out of range';
  END IF;

  SELECT * INTO cur FROM user_streaks s WHERE s.user_id = p_user_id FOR UPDATE;

  IF NOT FOUND THEN
    INSERT INTO user_streaks (user_id, current_streak, longest_streak, last_active_date, updated_at)
    VALUES (p_user_id, 1, 1, p_day, NOW());
  ELSIF cur.last_active_date IS NULL OR p_day > cur.last_active_date + 1 THEN
    UPDATE user_streaks
      SET current_streak = 1, last_active_date = p_day, updated_at = NOW()
      WHERE user_id = p_user_id;
  ELSIF p_day = cur.last_active_date + 1 THEN
    UPDATE user_streaks
      SET current_streak   = cur.current_streak + 1,
          longest_streak   = GREATEST(cur.longest_streak, cur.current_streak + 1),
          last_active_date = p_day,
          updated_at       = NOW()
      WHERE user_id = p_user_id;
  END IF;
  -- p_day <= last_active_date → already counted, fall through.

  RETURN QUERY
    SELECT s.current_streak, s.longest_streak, s.last_active_date
    FROM user_streaks s WHERE s.user_id = p_user_id;
END;
$$;

REVOKE ALL ON FUNCTION touch_streak(UUID, DATE) FROM PUBLIC;
REVOKE ALL ON FUNCTION touch_streak(UUID, DATE) FROM anon, authenticated;


-- ════════ supabase-migrations/013_app_attest.sql ════════
-- Run this in Supabase Dashboard > SQL Editor.
--
-- Apple App Attest support for the paid AI endpoints. Each iOS install
-- registers a Secure Enclave key once (attestation, verified by
-- /api/attest/register), then signs every paid request (assertion,
-- verified inline by api/_appAttest.js). Attested requests get the full
-- daily cap; unattested ones (web, old builds) get a reduced one.

-- ── Registered keys (service-role only) ─────────────────────────────────────
CREATE TABLE IF NOT EXISTS app_attest_keys (
  key_id         TEXT PRIMARY KEY,             -- base64 SHA256 of the public key
  user_id        UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  public_key_pem TEXT NOT NULL,                -- SPKI PEM extracted from credCert
  environment    TEXT NOT NULL DEFAULT 'production',
  counter        BIGINT NOT NULL DEFAULT 0,    -- last seen assertion counter
  attested_at    TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  last_used_at   TIMESTAMPTZ
);

ALTER TABLE app_attest_keys ENABLE ROW LEVEL SECURITY;
-- No policies: only the service role reads/writes these.

CREATE INDEX IF NOT EXISTS app_attest_keys_user_idx ON app_attest_keys (user_id);

-- ── One-time challenges (service-role only) ─────────────────────────────────
CREATE TABLE IF NOT EXISTS app_attest_challenges (
  id         UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id    UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  challenge  TEXT NOT NULL,
  used       BOOLEAN NOT NULL DEFAULT FALSE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

ALTER TABLE app_attest_challenges ENABLE ROW LEVEL SECURITY;

CREATE INDEX IF NOT EXISTS app_attest_challenges_created_idx
  ON app_attest_challenges (created_at);

-- ── RPC: consume_attest_challenge ───────────────────────────────────────────
-- Atomically marks a challenge used and returns it (NULL when missing,
-- already used, owned by someone else, or older than 10 minutes).
CREATE OR REPLACE FUNCTION consume_attest_challenge(p_id UUID, p_user_id UUID)
RETURNS TEXT
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_challenge TEXT;
BEGIN
  UPDATE app_attest_challenges
    SET used = TRUE
    WHERE id = p_id
      AND user_id = p_user_id
      AND NOT used
      AND created_at > NOW() - INTERVAL '10 minutes'
    RETURNING challenge INTO v_challenge;
  RETURN v_challenge;
END;
$$;

REVOKE ALL ON FUNCTION consume_attest_challenge(UUID, UUID) FROM PUBLIC;
REVOKE ALL ON FUNCTION consume_attest_challenge(UUID, UUID) FROM anon, authenticated;

-- ── RPC: bump_assertion_counter ─────────────────────────────────────────────
-- Advances the per-key assertion counter, but only forward — a replayed
-- assertion (counter <= stored) returns FALSE and changes nothing.
CREATE OR REPLACE FUNCTION bump_assertion_counter(p_key_id TEXT, p_user_id UUID, p_counter BIGINT)
RETURNS BOOLEAN
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  n INTEGER;
BEGIN
  UPDATE app_attest_keys
    SET counter = p_counter, last_used_at = NOW()
    WHERE key_id = p_key_id
      AND user_id = p_user_id
      AND p_counter > counter;
  GET DIAGNOSTICS n = ROW_COUNT;
  RETURN n > 0;
END;
$$;

REVOKE ALL ON FUNCTION bump_assertion_counter(TEXT, UUID, BIGINT) FROM PUBLIC;
REVOKE ALL ON FUNCTION bump_assertion_counter(TEXT, UUID, BIGINT) FROM anon, authenticated;


-- ════════ supabase-migrations/014_illustration_storage.sql ════════
-- Run this in Supabase Dashboard > SQL Editor.
--
-- Illustrations used to live only on the device as base64 data URLs, and
-- sync-books replaced them with the literal string '[saved-locally]' to
-- keep the user_books JSON small. The print pipeline reads that same
-- stored book, so every printed page rendered <img src="[saved-locally]">
-- — a broken image in a product people pay for.
--
-- Fix: illustrations go to Storage and the book keeps a plain URL, which
-- is small enough to sync and is fetchable by the PDF worker and by
-- Together's upscaler.
--
-- Public-read is deliberate: the PDF worker and Lulu fetch these by URL
-- with no session, and published gallery books are already public. Paths
-- are namespaced by user id and carry a random component, so they aren't
-- enumerable. Writes are service-role only (the generate-image endpoint).

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values (
  'book-illustrations',
  'book-illustrations',
  true,
  10485760, -- 10 MB; generated art is ~1 MB, a drawing far less
  array['image/png', 'image/jpeg', 'image/webp']
)
on conflict (id) do update
  set public = excluded.public,
      file_size_limit = excluded.file_size_limit,
      allowed_mime_types = excluded.allowed_mime_types;

-- Anyone may read (the PDF worker has no user session).
drop policy if exists "Illustrations are publicly readable" on storage.objects;
create policy "Illustrations are publicly readable"
  on storage.objects for select
  using (bucket_id = 'book-illustrations');

-- Signed-in users may write only under their own user-id prefix, so one
-- account cannot overwrite another's artwork. (The service role used by
-- api/generate-image.js bypasses RLS; this covers any direct client
-- upload, such as a drawing made in the app.)
drop policy if exists "Users write their own illustrations" on storage.objects;
create policy "Users write their own illustrations"
  on storage.objects for insert
  to authenticated
  with check (
    bucket_id = 'book-illustrations'
    and (storage.foldername(name))[1] = auth.uid()::text
  );

drop policy if exists "Users update their own illustrations" on storage.objects;
create policy "Users update their own illustrations"
  on storage.objects for update
  to authenticated
  using (
    bucket_id = 'book-illustrations'
    and (storage.foldername(name))[1] = auth.uid()::text
  );


-- ════════ supabase-migrations/015_user_inventory.sql ════════
-- Run this in Supabase Dashboard > SQL Editor.
--
-- Cross-device inventory. The avatar and any purchased art styles /
-- avatar items lived only in UserDefaults (iOS) and localStorage (web),
-- so the same account looked different on each device and clearing
-- browser data appeared to erase purchases.
--
-- Ownership is also made authoritative here. /api/spend-coins only ever
-- received an amount; the client then marked the item owned locally, so
-- anything could be granted for free by editing local storage. The spend
-- and the grant now happen together, in one transaction, server-side.

create table if not exists user_inventory (
  user_id      uuid primary key references auth.users(id) on delete cascade,
  avatar_url   text,
  owned_styles text[] not null default '{}',
  owned_items  text[] not null default '{}',
  updated_at   timestamptz not null default now()
);

alter table user_inventory enable row level security;

drop policy if exists "Users read own inventory" on user_inventory;
create policy "Users read own inventory"
  on user_inventory for select
  using (auth.uid() = user_id);

drop policy if exists "Users create own inventory" on user_inventory;
create policy "Users create own inventory"
  on user_inventory for insert to authenticated
  with check (auth.uid() = user_id);

drop policy if exists "Users update own inventory" on user_inventory;
create policy "Users update own inventory"
  on user_inventory for update to authenticated
  using (auth.uid() = user_id)
  with check (auth.uid() = user_id);

-- Column privileges are what keep ownership honest: a client may set its
-- own avatar, but owned_styles / owned_items are writable only by the
-- service role (via the RPC below). RLS alone cannot restrict columns.
revoke all on user_inventory from anon, authenticated;
grant select on user_inventory to authenticated;
grant insert (user_id, avatar_url) on user_inventory to authenticated;
grant update (avatar_url) on user_inventory to authenticated;

-- ── RPC: spend coins AND record what was bought, atomically ────────────────
-- Returns the new balance, or NULL when the user can't afford it (so the
-- caller can answer 402 exactly as before). p_kind is 'style' or 'item';
-- pass NULL to spend without granting anything.
create or replace function spend_coins_for(
  p_user_id uuid,
  p_amount int,
  p_kind text default null,
  p_id text default null
)
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  new_balance integer;
begin
  if p_amount <= 0 then
    raise exception 'amount must be positive';
  end if;

  update user_coins
    set balance = balance - p_amount,
        updated_at = now()
    where user_id = p_user_id
      and balance >= p_amount
    returning balance into new_balance;

  -- Not enough coins: change nothing and let the caller report it.
  if new_balance is null then
    return null;
  end if;

  if p_kind is not null and p_id is not null then
    insert into user_inventory (user_id, updated_at)
      values (p_user_id, now())
      on conflict (user_id) do nothing;

    if p_kind = 'style' then
      update user_inventory
        set owned_styles = (
              select array(select distinct unnest(owned_styles || array[p_id]))
            ),
            updated_at = now()
        where user_id = p_user_id;
    elsif p_kind = 'item' then
      update user_inventory
        set owned_items = (
              select array(select distinct unnest(owned_items || array[p_id]))
            ),
            updated_at = now()
        where user_id = p_user_id;
    else
      raise exception 'unknown kind %', p_kind;
    end if;
  end if;

  return new_balance;
end;
$$;

revoke all on function spend_coins_for(uuid, int, text, text) from public;
revoke all on function spend_coins_for(uuid, int, text, text) from anon, authenticated;


-- ════════ supabase-migrations/016_book_reports.sql ════════
-- Run this in Supabase Dashboard > SQL Editor
--
-- App Store Guideline 1.2 (user-generated content) requires an app that
-- shows other people's content to (a) filter objectionable material,
-- (b) let users report it, and (c) let users block abusive authors.
-- This migration is the (b) and (c) half; the filter runs at publish
-- time in api/publish-book.js.

-- ── Hiding ──────────────────────────────────────────────────────────
-- A book goes hidden either automatically (enough distinct reports) or
-- manually by us. Hidden books disappear from every public listing and
-- from the single-slug read, but the row is kept so we can review it.
ALTER TABLE published_books
  ADD COLUMN IF NOT EXISTS hidden BOOLEAN NOT NULL DEFAULT FALSE;

ALTER TABLE published_books
  ADD COLUMN IF NOT EXISTS hidden_reason TEXT;

ALTER TABLE published_books
  ADD COLUMN IF NOT EXISTS hidden_at TIMESTAMPTZ;

-- Public listings filter on this, so index it.
CREATE INDEX IF NOT EXISTS idx_published_books_visible
  ON published_books(published_at DESC)
  WHERE hidden = FALSE;

-- ── Reports ─────────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS book_reports (
  id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  slug TEXT NOT NULL REFERENCES published_books(slug) ON DELETE CASCADE,
  reporter_user_id UUID REFERENCES auth.users(id) ON DELETE SET NULL,
  reason TEXT NOT NULL,
  details TEXT,
  resolved BOOLEAN NOT NULL DEFAULT FALSE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  -- One report per person per book, so a single user can't hide a book
  -- on their own by reporting it repeatedly.
  UNIQUE (slug, reporter_user_id)
);

CREATE INDEX IF NOT EXISTS idx_book_reports_slug ON book_reports(slug);
CREATE INDEX IF NOT EXISTS idx_book_reports_open ON book_reports(created_at DESC) WHERE resolved = FALSE;

ALTER TABLE book_reports ENABLE ROW LEVEL SECURITY;
-- No public policies at all: reports are written by /api/report-book
-- with the service role, and only ever read by us. Without a policy,
-- RLS denies every anon/authenticated read and write by default.

-- ── Blocking an author ──────────────────────────────────────────────
-- A viewer can hide everything by a given author for themselves.
CREATE TABLE IF NOT EXISTS blocked_authors (
  id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  blocked_user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  UNIQUE (user_id, blocked_user_id)
);

CREATE INDEX IF NOT EXISTS idx_blocked_authors_user ON blocked_authors(user_id);

ALTER TABLE blocked_authors ENABLE ROW LEVEL SECURITY;

-- A signed-in user manages only their own block list.
DROP POLICY IF EXISTS "Users read their own blocks" ON blocked_authors;
CREATE POLICY "Users read their own blocks"
  ON blocked_authors FOR SELECT
  USING (auth.uid() = user_id);

DROP POLICY IF EXISTS "Users create their own blocks" ON blocked_authors;
CREATE POLICY "Users create their own blocks"
  ON blocked_authors FOR INSERT
  WITH CHECK (auth.uid() = user_id);

DROP POLICY IF EXISTS "Users remove their own blocks" ON blocked_authors;
CREATE POLICY "Users remove their own blocks"
  ON blocked_authors FOR DELETE
  USING (auth.uid() = user_id);

-- ── Report + auto-hide, atomically ──────────────────────────────────
-- Called by /api/report-book with the service role. Records the report
-- and hides the book once REPORT_THRESHOLD distinct people have flagged
-- it, so objectionable content comes down within seconds rather than
-- waiting for us to look. Returns the resulting report count.
CREATE OR REPLACE FUNCTION report_published_book(
  p_slug TEXT,
  p_reporter UUID,
  p_reason TEXT,
  p_details TEXT DEFAULT NULL
)
RETURNS TABLE (report_count INTEGER, now_hidden BOOLEAN)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_count INTEGER;
  v_hidden BOOLEAN;
  c_threshold CONSTANT INTEGER := 2;
BEGIN
  INSERT INTO book_reports (slug, reporter_user_id, reason, details)
  VALUES (p_slug, p_reporter, p_reason, p_details)
  ON CONFLICT (slug, reporter_user_id) DO UPDATE
    SET reason = EXCLUDED.reason,
        details = EXCLUDED.details;

  SELECT COUNT(*) INTO v_count
  FROM book_reports
  WHERE slug = p_slug AND resolved = FALSE;

  IF v_count >= c_threshold THEN
    UPDATE published_books
    SET hidden = TRUE,
        hidden_reason = 'auto: ' || v_count || ' reports',
        hidden_at = NOW()
    WHERE slug = p_slug AND hidden = FALSE;
  END IF;

  SELECT hidden INTO v_hidden FROM published_books WHERE slug = p_slug;

  RETURN QUERY SELECT v_count, COALESCE(v_hidden, FALSE);
END;
$$;

REVOKE ALL ON FUNCTION report_published_book(TEXT, UUID, TEXT, TEXT) FROM PUBLIC;
REVOKE ALL ON FUNCTION report_published_book(TEXT, UUID, TEXT, TEXT) FROM anon;


-- ════════ supabase-migrations/017_classroom_lockdown.sql ════════
-- Close the classroom tables to the public (anon) key.
--
-- classrooms and submissions carried four policies granting the `public` role
-- unconditional SELECT and INSERT. The anon key ships in the web bundle, so
-- anyone could read every classroom and every child's submitted book straight
-- from the Supabase REST API, and insert rows into either table.
--
-- api/classroom.js and api/classroom-submit.js now use the service-role key,
-- which bypasses RLS, so the API keeps working. With RLS still enabled and no
-- policies left, the anon and authenticated roles get nothing.
--
-- ORDER MATTERS: deploy the API change FIRST. Run this before it and the
-- classroom feature stops working until the deploy lands.
--
-- Idempotent.

alter table public.classrooms  enable row level security;
alter table public.submissions enable row level security;

drop policy if exists "Anyone can read classrooms"   on public.classrooms;
drop policy if exists "Anyone can insert classrooms" on public.classrooms;
drop policy if exists "Anyone can read submissions"   on public.submissions;
drop policy if exists "Anyone can insert submissions" on public.submissions;


-- ════════ supabase-migrations/018_schools_core.sql ════════
-- Schools, stage 1: class licenses, student accounts, sign-in throttle,
-- student check-ins and help asks.
--
-- Every table here is written and read ONLY by api/ with the service-role
-- key. RLS is enabled with no policies, so the anon and authenticated keys
-- (which ship to browsers) can read nothing. Do not add policies without a
-- design change: class_students holds the picture-password hash.
--
-- Apply BEFORE deploying the code that uses it: every change here is
-- additive with defaults, so the previous code keeps working; the new code
-- needs these tables from its first request (account purge, /teacher).

-- ── Licenses ────────────────────────────────────────────────────────────
create table if not exists public.class_licenses (
  id uuid primary key default gen_random_uuid(),
  owner_user_id uuid not null references auth.users(id) on delete restrict,
  classroom_id uuid unique references public.classrooms(id) on delete set null,
  origin text not null check (origin in ('trial','purchase','comp')),
  status text not null check (status in ('trial','pending_payment','active','grace','lapsed','canceled','comped')),
  billing_method text check (billing_method in ('card','invoice','manual')),
  seats int not null default 35 check (seats between 1 and 35),
  -- Default to 300 (trial allowance): if an insert forgets to set it, under-provision rather than grant paid 7,500.
  image_allowance int not null default 300 check (image_allowance >= 0),
  images_used int not null default 0 check (images_used >= 0),
  starts_at timestamptz not null default now(),
  expires_at timestamptz not null,
  stripe_customer_id text,
  stripe_subscription_id text,
  stripe_price_id text,
  school_name text,
  dpa_version text,
  dpa_accepted_at timestamptz,
  dpa_accepted_by uuid,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index if not exists class_licenses_owner_idx on public.class_licenses (owner_user_id);
alter table public.class_licenses enable row level security;

-- ── Classrooms (existing) ───────────────────────────────────────────────
alter table public.classrooms
  add column if not exists locale text not null default 'en' check (locale in ('en','it')),
  add column if not exists sign_in_open boolean not null default true,
  add column if not exists sign_in_paused_until timestamptz,
  add column if not exists archived_at timestamptz,
  add column if not exists timezone text not null default 'America/New_York',
  add column if not exists school_hours jsonb not null default
    '{"1":["08:00","15:30"],"2":["08:00","15:30"],"3":["08:00","15:30"],"4":["08:00","15:30"],"5":["08:00","15:30"]}'::jsonb;

-- A cascade would delete the classroom but leave its students' auth users
-- alive. Teacher deletion purges classes explicitly, in order (lib/deleteUser.js).
alter table public.classrooms drop constraint if exists classrooms_owner_user_id_fkey;
alter table public.classrooms add constraint classrooms_owner_user_id_fkey
  foreign key (owner_user_id) references auth.users(id) on delete restrict;

-- Legacy submissions reference the class CODE. Without ON UPDATE CASCADE,
-- rotating a code fails on any class that has legacy submissions.
alter table public.submissions drop constraint if exists submissions_classroom_code_fkey;
alter table public.submissions add constraint submissions_classroom_code_fkey
  foreign key (classroom_code) references public.classrooms(code) on update cascade on delete cascade;

-- So account deletion can find a signed-in child's legacy submissions.
alter table public.submissions
  add column if not exists user_id uuid references auth.users(id) on delete cascade;

-- ── Students ────────────────────────────────────────────────────────────
create table if not exists public.class_students (
  id uuid primary key default gen_random_uuid(),
  classroom_id uuid not null references public.classrooms(id) on delete restrict,
  auth_user_id uuid not null unique references auth.users(id) on delete cascade,
  display_name text not null check (char_length(display_name) between 1 and 24),
  avatar_emoji text not null,
  secret_hash text not null,
  secret_version smallint not null default 1,
  failed_attempts smallint not null default 0,
  locked_until timestamptz,
  hard_locked boolean not null default false,
  status text not null default 'active' check (status in ('active','removed')),
  images_day date,
  images_today int not null default 0,
  removed_at timestamptz,
  last_sign_in_at timestamptz,
  created_at timestamptz not null default now()
);
create unique index if not exists class_students_name_uniq
  on public.class_students (classroom_id, lower(display_name)) where status = 'active';
create index if not exists class_students_class_idx on public.class_students (classroom_id);
alter table public.class_students enable row level security;

-- ── Sign-in attempts (durable throttle; the in-memory limiter is per instance) ──
create table if not exists public.student_sign_in_attempts (
  id bigint generated always as identity primary key,
  classroom_id uuid not null references public.classrooms(id) on delete cascade,
  student_id uuid references public.class_students(id) on delete cascade,
  ip_hash text not null,
  ok boolean not null,
  created_at timestamptz not null default now()
);
create index if not exists ssia_class_time_idx on public.student_sign_in_attempts (classroom_id, created_at);
create index if not exists ssia_ip_time_idx on public.student_sign_in_attempts (ip_hash, created_at);
alter table public.student_sign_in_attempts enable row level security;

-- ── Check-ins shared with the teacher (student accounts only, spec §5a) ──
create table if not exists public.class_checkins (
  id uuid primary key default gen_random_uuid(),
  classroom_id uuid not null references public.classrooms(id) on delete cascade,
  student_id uuid not null references public.class_students(id) on delete cascade,
  feeling text not null check (feeling in ('happy','proud','tired','worried','angry','sad')),
  need text check (need in ('break','quiet','help_book','grownup','keep_going')),
  created_at timestamptz not null default now()
);
create index if not exists class_checkins_class_time_idx on public.class_checkins (classroom_id, created_at desc);
alter table public.class_checkins enable row level security;

-- ── Help asks (spec §12.1) ─────────────────────────────────────────────
create table if not exists public.class_help_requests (
  id uuid primary key default gen_random_uuid(),
  classroom_id uuid not null references public.classrooms(id) on delete cascade,
  student_id uuid not null references public.class_students(id) on delete cascade,
  kind text not null check (kind in ('book','grownup')),
  asks int not null default 1,
  in_hours boolean not null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  notified_at timestamptz,
  seen_at timestamptz,
  seen_by uuid references auth.users(id) on delete set null
);
create index if not exists class_help_open_idx on public.class_help_requests (student_id, kind, updated_at desc) where seen_at is null;
create index if not exists class_help_class_idx on public.class_help_requests (classroom_id, created_at desc);
alter table public.class_help_requests enable row level security;

-- ── RPCs (service role only) ────────────────────────────────────────────

-- One sign-in attempt, serialised per student by the row lock. The attempt
-- is recorded as a FAILURE before the pictures are compared; a right guess
-- is flipped to ok by school_confirm_attempt. So a parallel burst is counted
-- one at a time and at most 5 guesses fit in a lock window.
-- Returns {state: ok|not_found|ip_blocked|class_paused|hard_locked|locked,
--          attempt_id, after: ok|locked|hard_locked (what a WRONG guess leaves)}
create or replace function public.school_begin_attempt(p_classroom_id uuid, p_student_id uuid, p_ip_hash text)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  s record;
  paused timestamptz;
  fails smallint;
  attempt bigint;
begin
  select hard_locked, locked_until, failed_attempts into s
    from class_students
    where id = p_student_id and classroom_id = p_classroom_id and status = 'active'
    for update;
  if not found then return jsonb_build_object('state', 'not_found'); end if;

  -- A whole school shares one NAT'd IP, so this is set well above one class's typos.
  if (select count(*) from student_sign_in_attempts
      where ip_hash = p_ip_hash and not ok and created_at > now() - interval '1 hour') > 200 then
    return jsonb_build_object('state', 'ip_blocked');
  end if;
  select sign_in_paused_until into paused from classrooms where id = p_classroom_id;
  if paused is not null and paused > now() then return jsonb_build_object('state', 'class_paused'); end if;
  if s.hard_locked then return jsonb_build_object('state', 'hard_locked'); end if;
  if s.locked_until is not null and s.locked_until > now() then return jsonb_build_object('state', 'locked'); end if;

  insert into student_sign_in_attempts (classroom_id, student_id, ip_hash, ok)
    values (p_classroom_id, p_student_id, p_ip_hash, false)
    returning id into attempt;

  fails := s.failed_attempts + 1;
  update class_students set
    failed_attempts = fails,
    hard_locked = (fails >= 10),
    locked_until = case when fails < 10 and fails % 5 = 0 then now() + interval '15 minutes' else locked_until end
    where id = p_student_id;

  -- 30 young children mistype at the start of a lesson; 60 in 10 minutes is an attack.
  if (select count(*) from student_sign_in_attempts
      where classroom_id = p_classroom_id and not ok and created_at > now() - interval '10 minutes') > 60 then
    update classrooms set sign_in_paused_until = now() + interval '10 minutes' where id = p_classroom_id;
  end if;

  return jsonb_build_object(
    'state', 'ok',
    'attempt_id', attempt,
    'after', case when fails >= 10 then 'hard_locked' when fails % 5 = 0 then 'locked' else 'ok' end
  );
end $$;

-- The guess was right: turn the pessimistic failure into a success and clear
-- the counters. Returns ok, or invalid if the attempt is unknown/already used
-- or the student is no longer active (removed since the attempt began).
create or replace function public.school_confirm_attempt(p_attempt_id bigint, p_student_id uuid)
returns text language plpgsql security definer set search_path = public as $$
begin
  update student_sign_in_attempts set ok = true
    where id = p_attempt_id and student_id = p_student_id and not ok
      and exists (select 1 from class_students where id = p_student_id and status = 'active');
  if not found then return 'invalid'; end if;
  update class_students
    set failed_attempts = 0, locked_until = null, hard_locked = false, last_sign_in_at = now()
    where id = p_student_id;
  return 'ok';
end $$;

-- Atomically spend one AI image from the class allowance and the student's
-- daily allowance. Returns false (and spends nothing) if either is used up,
-- the class has no usable license, or the class is archived.
create or replace function public.school_bump_image(p_student_id uuid, p_daily_limit int)
returns boolean language plpgsql security definer set search_path = public as $$
declare
  st record;
  lic record;
  archived timestamptz;
begin
  select id, classroom_id, images_day, images_today into st
    from class_students where id = p_student_id and status = 'active' for update;
  if not found then return false; end if;

  select archived_at into archived from classrooms where id = st.classroom_id;
  if archived is not null then return false; end if;

  select id, status, expires_at, image_allowance, images_used into lic
    from class_licenses where classroom_id = st.classroom_id for update;
  if not found then return false; end if;
  if lic.status not in ('trial','active','grace','comped') then return false; end if;
  if lic.status <> 'grace' and lic.expires_at <= now() then return false; end if;
  if lic.images_used >= lic.image_allowance then return false; end if;

  if st.images_day is distinct from current_date then
    st.images_today := 0;
  end if;
  if st.images_today >= p_daily_limit then return false; end if;

  update class_licenses set images_used = images_used + 1, updated_at = now() where id = lic.id;
  update class_students set images_day = current_date, images_today = st.images_today + 1 where id = st.id;
  return true;
end $$;

-- "Sign out everywhere" for one student: drops every session (and with them
-- their refresh tokens). Access tokens already issued live until they expire.
create or replace function public.school_sign_out_user(p_user_id uuid)
returns void language plpgsql security definer set search_path = public as $$
begin
  delete from auth.sessions where user_id = p_user_id;
end $$;

revoke all on function public.school_begin_attempt(uuid, uuid, text) from public, anon, authenticated;
revoke all on function public.school_confirm_attempt(bigint, uuid) from public, anon, authenticated;
revoke all on function public.school_bump_image(uuid, int) from public, anon, authenticated;
revoke all on function public.school_sign_out_user(uuid) from public, anon, authenticated;
grant execute on function public.school_begin_attempt(uuid, uuid, text) to service_role;
grant execute on function public.school_confirm_attempt(bigint, uuid) to service_role;
grant execute on function public.school_bump_image(uuid, int) to service_role;
grant execute on function public.school_sign_out_user(uuid) to service_role;


-- ════════ supabase-migrations/019_assignments.sql ════════
-- Schools, stage 2: assignments, hand-ins and teacher feedback.
--
-- Same rules as 018: every table is read and written ONLY by api/ with the
-- service-role key. RLS is enabled with no policies, so the anon and
-- authenticated keys (which ship to browsers) can read nothing.
--
-- Every foreign key here cascades (or sets null), so deleting a classroom,
-- a student or an auth user is never blocked by these rows: lib/deleteUser.js
-- keeps its existing order and the new rows go with their parents.
--
-- Apply BEFORE deploying the code that uses it. Idempotent: safe to re-run.

-- ── Assignments ─────────────────────────────────────────────────────────
create table if not exists public.assignments (
  id uuid primary key default gen_random_uuid(),
  classroom_id uuid not null references public.classrooms(id) on delete cascade,
  title text not null check (char_length(title) between 1 and 80),
  prompt text not null check (char_length(prompt) between 1 and 1000),
  due_at timestamptz,
  status text not null default 'draft' check (status in ('draft','published','closed')),
  allow_late boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index if not exists assignments_class_time_idx on public.assignments (classroom_id, created_at desc);
alter table public.assignments enable row level security;

-- ── Hand-ins (one per student per assignment; resubmitting bumps version) ──
create table if not exists public.class_submissions (
  id uuid primary key default gen_random_uuid(),
  classroom_id uuid not null references public.classrooms(id) on delete cascade,
  assignment_id uuid not null references public.assignments(id) on delete cascade,
  student_id uuid not null references public.class_students(id) on delete cascade,
  user_id uuid not null references auth.users(id) on delete cascade,
  book_id text not null,
  book_title text not null default '',
  book_snapshot jsonb not null,
  version int not null default 1,
  submitted_at timestamptz not null default now(),
  unique (assignment_id, student_id)
);
create index if not exists class_submissions_class_time_idx on public.class_submissions (classroom_id, submitted_at desc);
-- Student reads ("my hand-ins") and the student-FK cascade; account purge by user.
create index if not exists class_submissions_student_idx on public.class_submissions (student_id);
create index if not exists class_submissions_user_idx on public.class_submissions (user_id);
alter table public.class_submissions enable row level security;

-- ── Teacher feedback: a short comment and/or one sticker from a fixed set ──
create table if not exists public.submission_feedback (
  id uuid primary key default gen_random_uuid(),
  submission_id uuid not null references public.class_submissions(id) on delete cascade,
  author_user_id uuid references auth.users(id) on delete set null,
  comment text check (char_length(comment) <= 500),
  sticker text check (sticker in ('star','rocket','heart','wow','keep_going','rainbow')),
  created_at timestamptz not null default now(),
  seen_at timestamptz,
  check (comment is not null or sticker is not null)
);
create index if not exists submission_feedback_sub_time_idx on public.submission_feedback (submission_id, created_at desc);
alter table public.submission_feedback enable row level security;

-- ── RPCs (service role only) ────────────────────────────────────────────
-- Errors are raised with a bare message (SQLSTATE P0001); PostgREST returns
-- it as {code:'P0001', message:'<name>'} and api/ maps the name to a status.

-- Hand in (or hand in again). The assignment is re-checked here, under a
-- share lock and against the database clock, so a teacher closing it (or the
-- due date passing) between the API's fast pre-check and this write can't
-- let a hand-in through. The upsert is one statement, so two taps at once
-- can never both write the same version: ON CONFLICT serialises them.
-- Returns {id, version, submitted_at}.
create or replace function public.school_submit(
  p_classroom_id uuid, p_assignment_id uuid, p_student_id uuid, p_user_id uuid,
  p_book_id text, p_book_title text, p_book_snapshot jsonb
)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  a record;
  r record;
begin
  select status, due_at, allow_late into a
    from assignments where id = p_assignment_id and classroom_id = p_classroom_id
    for share;
  if not found or a.status = 'draft' then raise exception 'assignment_not_found'; end if;
  if a.status = 'closed' then raise exception 'assignment_closed'; end if;
  if not a.allow_late and a.due_at is not null and now() > a.due_at then
    raise exception 'past_due';
  end if;

  insert into class_submissions (classroom_id, assignment_id, student_id, user_id, book_id, book_title, book_snapshot)
    values (p_classroom_id, p_assignment_id, p_student_id, p_user_id, p_book_id, coalesce(p_book_title, ''), p_book_snapshot)
  on conflict (assignment_id, student_id) do update set
    book_id = excluded.book_id,
    book_title = excluded.book_title,
    book_snapshot = excluded.book_snapshot,
    user_id = excluded.user_id,
    version = class_submissions.version + 1,
    submitted_at = now()
  returning id, version, submitted_at into r;
  return jsonb_build_object('id', r.id, 'version', r.version, 'submitted_at', r.submitted_at);
end $$;

-- Delete an assignment nobody has handed in. The row lock (FOR UPDATE)
-- conflicts with school_submit's FOR SHARE, so a hand-in can't land between
-- the "no submissions" check and the delete and then vanish in the cascade.
create or replace function public.school_delete_assignment(p_classroom_id uuid, p_assignment_id uuid)
returns void language plpgsql security definer set search_path = public as $$
begin
  perform 1
    from assignments where id = p_assignment_id and classroom_id = p_classroom_id
    for update;
  if not found then raise exception 'assignment_not_found'; end if;
  if exists (select 1 from class_submissions where assignment_id = p_assignment_id) then
    raise exception 'has_submissions';
  end if;
  delete from assignments where id = p_assignment_id;
end $$;

revoke all on function public.school_submit(uuid, uuid, uuid, uuid, text, text, jsonb) from public, anon, authenticated;
revoke all on function public.school_delete_assignment(uuid, uuid) from public, anon, authenticated;
grant execute on function public.school_submit(uuid, uuid, uuid, uuid, text, text, jsonb) to service_role;
grant execute on function public.school_delete_assignment(uuid, uuid) to service_role;


-- ════════ supabase-migrations/020_notifications.sql ════════
-- Schools, stage 3: teacher notifications (spec §12).
--
-- Same rules as 018/019: every table is read and written ONLY by api/ with
-- the service-role key. RLS is enabled with no policies, and the client
-- roles' table grants are revoked too, so the anon and authenticated keys
-- (which ship to browsers) can read nothing.
--
-- Every foreign key cascades, so deleting a classroom or an auth user is
-- never blocked by these rows: lib/deleteUser.js keeps its existing order.
--
-- class_help_requests.notified_at already exists (018).
--
-- Apply BEFORE deploying the code that uses it. Idempotent: safe to re-run.

-- ── The bell: one row per event a teacher should hear about ─────────────
-- payload carries ids and display text only (student_id — the name is
-- resolved at read time — class name, assignment title/id). Never a
-- feeling or a need. Rows older than 90 days are pruned by
-- api/cron/purge-deletions.js.
-- dedup_key: set only for events that must fire once ("everyone has handed
-- in <assignment>"); the insert uses ON CONFLICT DO NOTHING on it, so two
-- last hand-ins landing at once cannot both alert. NULLs never conflict.
create table if not exists public.teacher_notifications (
  id uuid primary key default gen_random_uuid(),
  teacher_user_id uuid not null references auth.users(id) on delete cascade,
  classroom_id uuid references public.classrooms(id) on delete cascade,
  kind text not null check (kind in ('hand_in','hand_in_late','resubmit','all_handed_in','help_book','help_grownup')),
  payload jsonb not null default '{}'::jsonb,
  dedup_key text unique,
  created_at timestamptz not null default now(),
  read_at timestamptz
);
create index if not exists teacher_notifications_teacher_time_idx
  on public.teacher_notifications (teacher_user_id, created_at desc);
-- The classroom-FK cascade.
create index if not exists teacher_notifications_class_idx on public.teacher_notifications (classroom_id);
-- The 90-day prune.
create index if not exists teacher_notifications_created_idx on public.teacher_notifications (created_at);
alter table public.teacher_notifications enable row level security;
revoke all on public.teacher_notifications from anon, authenticated;

-- ── Web push subscriptions (one per browser) ────────────────────────────
create table if not exists public.push_subscriptions (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  endpoint text unique not null,
  p256dh text not null,
  auth text not null,
  created_at timestamptz not null default now(),
  last_used_at timestamptz
);
create index if not exists push_subscriptions_user_idx on public.push_subscriptions (user_id);
alter table public.push_subscriptions enable row level security;
revoke all on public.push_subscriptions from anon, authenticated;

-- ── APNs device tokens (iPad / iPhone teachers) ─────────────────────────
create table if not exists public.device_tokens (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  token text unique not null,
  platform text not null default 'ios' check (platform in ('ios')),
  env text not null default 'production' check (env in ('production','sandbox')),
  created_at timestamptz not null default now(),
  last_used_at timestamptz
);
create index if not exists device_tokens_user_idx on public.device_tokens (user_id);
alter table public.device_tokens enable row level security;
revoke all on public.device_tokens from anon, authenticated;

-- ── Per-teacher notification settings (no row = the defaults) ───────────
create table if not exists public.teacher_settings (
  user_id uuid primary key references auth.users(id) on delete cascade,
  summary text not null default 'daily' check (summary in ('daily','weekly','off')),
  push_urgent boolean not null default true,
  email_urgent boolean not null default true,
  updated_at timestamptz not null default now()
);
-- When the summary cron last emailed this teacher (activity is counted
-- since then). Added separately so a re-run on an older 020 is safe.
alter table public.teacher_settings add column if not exists last_summary_at timestamptz;
alter table public.teacher_settings enable row level security;
revoke all on public.teacher_settings from anon, authenticated;


-- ════════ supabase-migrations/021_nudges.sql ════════
-- Schools: teacher nudges — a short, encouraging note from a teacher to a
-- child who hasn't written in a while ("Your story is waiting for you!").
--
-- Same rules as 018/019/020: every table is read and written ONLY by api/
-- with the service-role key. RLS is enabled with no policies, and the client
-- roles' table grants are revoked too, so the anon and authenticated keys
-- (which ship to browsers) can read nothing.
--
-- Deletion: class_nudges cascades from classrooms and from class_students,
-- and teacher_user_id is ON DELETE SET NULL, so neither purgeClassroom nor
-- purgeUser in lib/deleteUser.js is ever blocked by these rows and the
-- existing purge order is unchanged (students are purged first; their
-- class_students rows cascade from auth.users, and their nudges with them).
--
-- Apply BEFORE deploying the code that uses it. Idempotent: safe to re-run.

-- ── Nudges ──────────────────────────────────────────────────────────────
-- A preset is stored as a key (the child's app renders it in the child's
-- language); a custom message is stored as the teacher wrote it.
-- assignment_id CASCADES (not SET NULL): a 'hand_in' nudge must name an
-- assignment (the last check below), so SET NULL would make deleting that
-- assignment fail the check and block school_delete_assignment. A nudge
-- about an assignment that no longer exists has nothing left to say.
create table if not exists public.class_nudges (
  id uuid primary key default gen_random_uuid(),
  classroom_id uuid not null references public.classrooms(id) on delete cascade,
  student_id uuid not null references public.class_students(id) on delete cascade,
  teacher_user_id uuid references auth.users(id) on delete set null,
  teacher_name text not null default '' check (char_length(teacher_name) <= 60),
  preset text check (preset in ('story_waiting','one_more_page','cant_wait','hand_in')),
  message text check (char_length(message) <= 140),
  assignment_id uuid references public.assignments(id) on delete cascade,
  created_at timestamptz not null default now(),
  seen_at timestamptz,
  check (preset is not null or message is not null),
  check (preset <> 'hand_in' or assignment_id is not null)
);
-- "Latest nudge per child" (teacher) and "my unread nudge" (child).
create index if not exists class_nudges_student_time_idx on public.class_nudges (student_id, created_at desc);
-- One unread nudge per child at a time: a new one replaces it (see the RPC).
create unique index if not exists class_nudges_one_unread_idx on public.class_nudges (student_id) where seen_at is null;
-- The classroom-FK cascade and the teacher's per-class read.
create index if not exists class_nudges_class_time_idx on public.class_nudges (classroom_id, created_at desc);
-- The assignment-FK cascade.
create index if not exists class_nudges_assignment_idx on public.class_nudges (assignment_id);
alter table public.class_nudges enable row level security;
revoke all on public.class_nudges from anon, authenticated;

-- ── Daily cap counter (same pattern as images_day / images_today) ───────
-- A replaced unread nudge is deleted, so counting class_nudges rows would
-- let a teacher resend forever. The count lives on the student row instead,
-- keyed by the calendar day in the CLASS's timezone.
alter table public.class_students add column if not exists nudges_day date;
alter table public.class_students add column if not exists nudges_today int not null default 0;

-- ── RPC (service role only) ─────────────────────────────────────────────
-- Errors are raised with a bare message (SQLSTATE P0001); PostgREST returns
-- it as {code:'P0001', message:'<name>'} and api/ maps the name.
--
-- Sends one nudge to one child. The student row is locked FOR UPDATE, so
-- two sends at once serialise: the daily cap can't be exceeded and the
-- one-unread rule can't trip the unique index. Returns the new row.
--
-- Re-checked here, against the database clock, whatever the API already
-- checked: the class is not archived; a linked assignment is published and
-- still OPEN (not past a due date that disallows late work); a 'hand_in'
-- nudge never reaches a child who has already handed that assignment in.
create or replace function public.school_send_nudge(
  p_classroom_id uuid, p_student_id uuid, p_teacher_user_id uuid, p_teacher_name text,
  p_preset text, p_message text, p_assignment_id uuid, p_daily_cap int
)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  st record;
  tz text;
  archived timestamptz;
  today date;
  sent int;
  r record;
begin
  select id, nudges_day, nudges_today into st
    from class_students
    where id = p_student_id and classroom_id = p_classroom_id and status = 'active'
    for update;
  if not found then raise exception 'student_not_found'; end if;

  select coalesce(nullif(timezone, ''), 'UTC'), archived_at into tz, archived
    from classrooms where id = p_classroom_id;
  if archived is not null then raise exception 'class_archived'; end if;

  if p_assignment_id is not null then
    perform 1 from assignments
      where id = p_assignment_id and classroom_id = p_classroom_id and status = 'published'
        and (allow_late or due_at is null or due_at >= now());
    if not found then raise exception 'assignment_not_found'; end if;
    if p_preset = 'hand_in' and exists (
      select 1 from class_submissions where assignment_id = p_assignment_id and student_id = p_student_id
    ) then
      raise exception 'handed_in';
    end if;
  end if;

  begin
    today := (now() at time zone tz)::date;
  exception when others then
    today := (now() at time zone 'UTC')::date;
  end;

  sent := case when st.nudges_day is distinct from today then 0 else st.nudges_today end;
  if sent >= p_daily_cap then raise exception 'daily_cap'; end if;

  delete from class_nudges where student_id = p_student_id and seen_at is null;
  insert into class_nudges (classroom_id, student_id, teacher_user_id, teacher_name, preset, message, assignment_id)
    values (p_classroom_id, p_student_id, p_teacher_user_id, left(coalesce(p_teacher_name, ''), 60),
            p_preset, p_message, p_assignment_id)
    returning id, student_id, created_at into r;
  update class_students set nudges_day = today, nudges_today = sent + 1 where id = p_student_id;
  return jsonb_build_object('id', r.id, 'student_id', r.student_id, 'created_at', r.created_at);
end $$;

revoke all on function public.school_send_nudge(uuid, uuid, uuid, text, text, text, uuid, int) from public, anon, authenticated;
grant execute on function public.school_send_nudge(uuid, uuid, uuid, text, text, text, uuid, int) to service_role;


-- ════════ supabase-migrations/022_grading.sql ════════
-- Schools: grading with tips — a child-facing level and 0–3 tips on a
-- hand-in, and "send back to revise" (Try again).
--
-- Same rules as 018–021: every table is read and written ONLY by api/ with
-- the service-role key. RLS is enabled with no policies, and the client
-- roles' table grants are revoked too, so the anon and authenticated keys
-- (which ship to browsers) can read nothing.
--
-- Deletion: submission_grades cascades from class_submissions, which already
-- cascades from classrooms, assignments, class_students and auth.users (019).
-- author_user_id is ON DELETE SET NULL. So purgeUser (which deletes the
-- child's class_submissions by user_id, then the auth user) and
-- purgeClassroom (students first, then the classroom) take the grades with
-- the hand-ins, and neither is ever blocked by these rows: the purge order in
-- lib/deleteUser.js is unchanged. Grades are part of the child's data.
--
-- Apply BEFORE deploying the code that uses it. Idempotent: safe to re-run.

-- ── Tips: the shape check, shared by the table and the RPC ─────────────
-- A JSON array of at most 3 tips, each exactly {"key": "<skill>.<tip>"} (a
-- library tip; api/ checks it against lib/school/grading.js) or
-- {"text": "<1–140 chars>"} (a custom tip). Immutable, so usable in a CHECK.
create or replace function public.school_valid_tips(t jsonb)
returns boolean language sql immutable set search_path = public as $$
  select case when coalesce(jsonb_typeof(t), '') <> 'array' then false
  else jsonb_array_length(t) <= 3
     and not exists (
       select 1 from jsonb_array_elements(t) e
       where not (
         -- CASE, not AND: SQL doesn't promise short-circuiting, and
         -- jsonb_object_keys raises on a non-object. COALESCE: a missing
         -- key makes its branch NULL, not false, and NOT NULL would let
         -- the element through.
         case when jsonb_typeof(e) <> 'object' then false
         else coalesce(
           (select count(*) from jsonb_object_keys(e)) = 1
           and (
             (jsonb_typeof(e->'key') = 'string' and (e->>'key') ~ '^[a-z]+\.[a-z_]+$' and char_length(e->>'key') <= 40)
             or
             (jsonb_typeof(e->'text') = 'string' and char_length(e->>'text') between 1 and 140)
           ),
           false)
         end
       )
     )
  end
$$;

-- ── Grades (one per hand-in VERSION; re-grading a version replaces it) ──
-- Keyed by version, so the teacher keeps the history: v1 "Growing, sent back
-- with tips", v2 "Got it!". `returned` records whether THAT version was sent
-- back; the live "sent back, waiting for the child" state is
-- class_submissions.returned_at below.
create table if not exists public.submission_grades (
  id uuid primary key default gen_random_uuid(),
  submission_id uuid not null references public.class_submissions(id) on delete cascade,
  version int not null check (version >= 1),
  level text not null check (level in ('getting_started','growing','got_it','wow')),
  tips jsonb not null default '[]'::jsonb check (public.school_valid_tips(tips)),
  returned boolean not null default false,
  author_user_id uuid references auth.users(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  seen_at timestamptz,
  unique (submission_id, version)
);
-- The unique (submission_id, version) index serves every read: the
-- per-assignment grid and the per-student history both find their
-- class_submissions rows first (class_submissions_student_idx and the
-- (assignment_id, student_id) unique index from 019), then read grades by
-- submission_id in (...); and it serves the cascade from class_submissions.
-- The teacher-wide CSV read goes through class_submissions_class_time_idx.
alter table public.submission_grades enable row level security;
revoke all on public.submission_grades from anon, authenticated;

-- ── "Sent back to revise" on the hand-in itself ─────────────────────────
-- Set by school_grade_submission when the teacher sends it back; cleared by
-- a re-grade without "send back", and by the child handing in again
-- (school_submit below), which also bumps the version.
alter table public.class_submissions add column if not exists returned_at timestamptz;

-- ── RPCs (service role only) ────────────────────────────────────────────
-- Errors are raised with a bare message (SQLSTATE P0001); PostgREST returns
-- it as {code:'P0001', message:'<name>'} and api/ maps the name.

-- Grade one hand-in. The hand-in row is locked FOR UPDATE, which conflicts with
-- school_submit's ON CONFLICT update, so a resubmission can't land between
-- the version check and the write: a grade always belongs to the version the
-- teacher was looking at, and a stale screen gets 'version_changed'.
--
-- Sending back is only allowed while the child can actually hand in again:
-- the assignment is published and not past a due date that refuses late
-- work (the same rule school_submit applies), else 'cannot_return'.
-- Returns {grade: {...}}. Stickers and comments stay on their own route
-- (submission_feedback, api/school/feedback.js).
-- An earlier draft of this migration had a 9-argument version (with
-- comment/sticker). Never applied, but dropped by its exact signature so a
-- database that ever saw it can't keep a stale overload callable.
drop function if exists public.school_grade_submission(uuid, uuid, int, uuid, text, jsonb, boolean, text, text);

create or replace function public.school_grade_submission(
  p_classroom_id uuid, p_submission_id uuid, p_version int, p_author_user_id uuid,
  p_level text, p_tips jsonb, p_returned boolean
)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  s record;
  a record;
  g record;
begin
  select id, version, assignment_id into s
    from class_submissions
    where id = p_submission_id and classroom_id = p_classroom_id
    for update;
  if not found then raise exception 'submission_not_found'; end if;
  if s.version <> p_version then raise exception 'version_changed'; end if;

  if p_returned then
    select status, due_at, allow_late into a from assignments where id = s.assignment_id;
    if not found or a.status <> 'published'
       or (not a.allow_late and a.due_at is not null and now() > a.due_at) then
      raise exception 'cannot_return';
    end if;
  end if;

  insert into submission_grades (submission_id, version, level, tips, returned, author_user_id)
    values (s.id, s.version, p_level, coalesce(p_tips, '[]'::jsonb), coalesce(p_returned, false), p_author_user_id)
  on conflict (submission_id, version) do update set
    level = excluded.level,
    tips = excluded.tips,
    returned = excluded.returned,
    author_user_id = excluded.author_user_id,
    updated_at = now(),
    -- A changed grade is news to the child again.
    seen_at = null
  returning id, version, level, tips, returned, created_at, updated_at, seen_at into g;

  update class_submissions
    set returned_at = case when coalesce(p_returned, false) then now() else null end
    where id = s.id;

  return jsonb_build_object(
    'grade', jsonb_build_object('id', g.id, 'version', g.version, 'level', g.level, 'tips', g.tips,
                                'returned', g.returned, 'created_at', g.created_at,
                                'updated_at', g.updated_at, 'seen_at', g.seen_at)
  );
end $$;

-- school_submit (019), unchanged except that handing in again clears
-- returned_at (the revision is in, so it is no longer "sent back") and the
-- result says whether the hand-in it replaced HAD been sent back
-- (was_returned): only then can a resubmission complete the class, so only
-- then does api/ re-run the "everyone has handed in" check. The existing row
-- is read FOR UPDATE first, so a send-back can't land between that read and
-- the upsert.
create or replace function public.school_submit(
  p_classroom_id uuid, p_assignment_id uuid, p_student_id uuid, p_user_id uuid,
  p_book_id text, p_book_title text, p_book_snapshot jsonb
)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  a record;
  r record;
  was_returned boolean := false;
begin
  select status, due_at, allow_late into a
    from assignments where id = p_assignment_id and classroom_id = p_classroom_id
    for share;
  if not found or a.status = 'draft' then raise exception 'assignment_not_found'; end if;
  if a.status = 'closed' then raise exception 'assignment_closed'; end if;
  if not a.allow_late and a.due_at is not null and now() > a.due_at then
    raise exception 'past_due';
  end if;

  select returned_at is not null into was_returned
    from class_submissions where assignment_id = p_assignment_id and student_id = p_student_id
    for update;
  was_returned := coalesce(was_returned, false);

  insert into class_submissions (classroom_id, assignment_id, student_id, user_id, book_id, book_title, book_snapshot)
    values (p_classroom_id, p_assignment_id, p_student_id, p_user_id, p_book_id, coalesce(p_book_title, ''), p_book_snapshot)
  on conflict (assignment_id, student_id) do update set
    book_id = excluded.book_id,
    book_title = excluded.book_title,
    book_snapshot = excluded.book_snapshot,
    user_id = excluded.user_id,
    version = class_submissions.version + 1,
    submitted_at = now(),
    returned_at = null
  returning id, version, submitted_at into r;
  return jsonb_build_object('id', r.id, 'version', r.version, 'submitted_at', r.submitted_at,
                            'was_returned', was_returned);
end $$;

-- school_send_nudge (021), unchanged except that a hand-in the teacher
-- SENT BACK no longer counts as handed in: "Don't forget to hand in" may
-- reach a child who is revising. Owner ruling: a sent-back hand-in is not
-- done (nudge pre-ticks, the all-handed-in alert, the daily summary and the
-- dashboard's handed-in counts all read it the same way).
create or replace function public.school_send_nudge(
  p_classroom_id uuid, p_student_id uuid, p_teacher_user_id uuid, p_teacher_name text,
  p_preset text, p_message text, p_assignment_id uuid, p_daily_cap int
)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  st record;
  tz text;
  archived timestamptz;
  today date;
  sent int;
  r record;
begin
  select id, nudges_day, nudges_today into st
    from class_students
    where id = p_student_id and classroom_id = p_classroom_id and status = 'active'
    for update;
  if not found then raise exception 'student_not_found'; end if;

  select coalesce(nullif(timezone, ''), 'UTC'), archived_at into tz, archived
    from classrooms where id = p_classroom_id;
  if archived is not null then raise exception 'class_archived'; end if;

  if p_assignment_id is not null then
    perform 1 from assignments
      where id = p_assignment_id and classroom_id = p_classroom_id and status = 'published'
        and (allow_late or due_at is null or due_at >= now());
    if not found then raise exception 'assignment_not_found'; end if;
    if p_preset = 'hand_in' and exists (
      select 1 from class_submissions where assignment_id = p_assignment_id and student_id = p_student_id
        and returned_at is null
    ) then
      raise exception 'handed_in';
    end if;
  end if;

  begin
    today := (now() at time zone tz)::date;
  exception when others then
    today := (now() at time zone 'UTC')::date;
  end;

  sent := case when st.nudges_day is distinct from today then 0 else st.nudges_today end;
  if sent >= p_daily_cap then raise exception 'daily_cap'; end if;

  delete from class_nudges where student_id = p_student_id and seen_at is null;
  insert into class_nudges (classroom_id, student_id, teacher_user_id, teacher_name, preset, message, assignment_id)
    values (p_classroom_id, p_student_id, p_teacher_user_id, left(coalesce(p_teacher_name, ''), 60),
            p_preset, p_message, p_assignment_id)
    returning id, student_id, created_at into r;
  update class_students set nudges_day = today, nudges_today = sent + 1 where id = p_student_id;
  return jsonb_build_object('id', r.id, 'student_id', r.student_id, 'created_at', r.created_at);
end $$;

revoke all on function public.school_valid_tips(jsonb) from public, anon, authenticated;
revoke all on function public.school_grade_submission(uuid, uuid, int, uuid, text, jsonb, boolean) from public, anon, authenticated;
revoke all on function public.school_submit(uuid, uuid, uuid, uuid, text, text, jsonb) from public, anon, authenticated;
-- The tips check runs as whoever writes the row: only ever the service role
-- (or the RPC's owner).
grant execute on function public.school_valid_tips(jsonb) to service_role;
grant execute on function public.school_grade_submission(uuid, uuid, int, uuid, text, jsonb, boolean) to service_role;
grant execute on function public.school_submit(uuid, uuid, uuid, uuid, text, text, jsonb) to service_role;
revoke all on function public.school_send_nudge(uuid, uuid, uuid, text, text, text, uuid, int) from public, anon, authenticated;
grant execute on function public.school_send_nudge(uuid, uuid, uuid, text, text, text, uuid, int) to service_role;


-- ════════ supabase-migrations/023_worksheets.sql ════════
-- Schools: worksheet assignments (spec 2026-10-01 §2). A teacher assigns
-- either a book (as before) or a worksheet: a template (lib/school/
-- worksheets.js) whose box prompts the teacher may edit.
--
-- Same rules as 018–022: every table is read and written ONLY by api/ with
-- the service-role key. Nothing here adds a table, a policy or a grant to
-- the client roles.
--
-- Where a worksheet hand-in lives — the least invasive choice:
-- class_submissions is unchanged. A worksheet hand-in is a row like any
-- other, with
--   book_id       = 'worksheet:<assignment id>'  (not a user_books key)
--   book_title    = the assignment's title
--   book_snapshot = { "kind": "worksheet", "templateId", "word"?,
--                     "boxes": [{ "id", "prompt" }],   -- prompts as the
--                     "answers": { "<boxId>": "..." } } -- child saw them
-- So grading (022: school_grade_submission, submission_grades, returned_at),
-- feedback, the dashboard, nudges, the all-handed-in alert, the summary and
-- the account/class purge all work on it unchanged: none of them read the
-- snapshot. No server drafts: answers are autosaved on the child's device.
--
-- Deletion: nothing new to purge. The worksheet definition is teacher text
-- on the assignment (cascades with the class); the child's answers are in
-- class_submissions, which 019 already cascades and lib/deleteUser.js
-- already deletes.
--
-- Apply BEFORE deploying the code that uses it. Idempotent: safe to re-run.

-- ── The worksheet shape check (mirrors lib/school/worksheets.js) ───────
-- An object {templateId, prompts, word?}: templateId a template-id-shaped
-- string; prompts an object of 1–12 box-id-shaped keys, each a string of
-- 1–300 characters; word (the acrostic's, optional) 2–12 letters. Which
-- template ids and box ids exist is checked by api/ against the template
-- list (the SQL can't follow a list that grows in code). CASE, not AND,
-- wherever a function would raise on the wrong JSON type: SQL doesn't
-- promise short-circuiting.
create or replace function public.school_valid_worksheet(w jsonb)
returns boolean language sql immutable set search_path = public as $$
  select case when coalesce(jsonb_typeof(w), '') <> 'object' then false
  else coalesce(
    jsonb_typeof(w->'templateId') = 'string'
    and (w->>'templateId') ~ '^[a-z_]{1,40}$'
    and not exists (
      select 1 from jsonb_object_keys(w) k where k not in ('templateId', 'prompts', 'word')
    )
    and (case when jsonb_typeof(w->'prompts') <> 'object' then false
         else (select count(*) from jsonb_object_keys(w->'prompts')) between 1 and 12
           and not exists (
             select 1 from jsonb_each(w->'prompts') p
             where not (
               p.key ~ '^[a-z_]{1,40}$'
               and jsonb_typeof(p.value) = 'string'
               and char_length(p.value #>> '{}') between 1 and 300
             )
           )
         end)
    and (case when not (w ? 'word') then true
         when jsonb_typeof(w->'word') <> 'string' then false
         else (w->>'word') ~ '^[[:alpha:]]{2,12}$'
         end),
    false)
  end
$$;

-- ── Assignments: book or worksheet ─────────────────────────────────────
alter table public.assignments add column if not exists kind text not null default 'book';
alter table public.assignments add column if not exists worksheet jsonb;

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'assignments_kind_check'
                 and conrelid = 'public.assignments'::regclass) then
    alter table public.assignments add constraint assignments_kind_check
      check (kind in ('book', 'worksheet'));
  end if;
  -- A book carries no worksheet; a worksheet always carries a valid one.
  if not exists (select 1 from pg_constraint where conname = 'assignments_worksheet_check'
                 and conrelid = 'public.assignments'::regclass) then
    alter table public.assignments add constraint assignments_worksheet_check
      check ((kind = 'book' and worksheet is null)
          or (kind = 'worksheet' and public.school_valid_worksheet(worksheet)));
  end if;
  -- 019's inline prompt check (1-1000 characters) becomes: a worksheet's
  -- class-wide instructions may be empty (its boxes carry the prompts); a
  -- book's prompt is still 1-1000.
  if not exists (select 1 from pg_constraint where conname = 'assignments_prompt_kind_check'
                 and conrelid = 'public.assignments'::regclass) then
    alter table public.assignments drop constraint if exists assignments_prompt_check;
    alter table public.assignments add constraint assignments_prompt_kind_check
      check (char_length(prompt) <= 1000 and (kind = 'worksheet' or char_length(prompt) >= 1));
  end if;
end $$;

-- What an assignment IS never changes once created: hand-ins (and a
-- child's device draft) are of that kind. api/ never sends kind on an
-- update; this makes it a rule, not a habit.
create or replace function public.school_assignment_kind_locked()
returns trigger language plpgsql set search_path = public as $$
begin
  if new.kind is distinct from old.kind then raise exception 'kind_locked'; end if;
  return new;
end $$;

drop trigger if exists assignments_kind_locked on public.assignments;
create trigger assignments_kind_locked before update of kind on public.assignments
  for each row execute function public.school_assignment_kind_locked();

-- ── school_submit (022), unchanged except for one check ───────────────
-- The hand-in must match the assignment's kind: a worksheet assignment
-- takes only a worksheet snapshot, a book assignment only a book. Read
-- under the same FOR SHARE lock as the status re-check ('wrong_kind').
-- Everything else is 022's, word for word: the closed/draft/past_due
-- re-check against the database clock, the FOR UPDATE read of the existing
-- row for was_returned, the one-statement upsert that bumps the version,
-- and returned_at cleared on handing in again.
create or replace function public.school_submit(
  p_classroom_id uuid, p_assignment_id uuid, p_student_id uuid, p_user_id uuid,
  p_book_id text, p_book_title text, p_book_snapshot jsonb
)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  a record;
  r record;
  was_returned boolean := false;
begin
  select status, due_at, allow_late, kind into a
    from assignments where id = p_assignment_id and classroom_id = p_classroom_id
    for share;
  if not found or a.status = 'draft' then raise exception 'assignment_not_found'; end if;
  if a.status = 'closed' then raise exception 'assignment_closed'; end if;
  if not a.allow_late and a.due_at is not null and now() > a.due_at then
    raise exception 'past_due';
  end if;
  if (a.kind = 'worksheet') is distinct from (coalesce(p_book_snapshot->>'kind', '') = 'worksheet') then
    raise exception 'wrong_kind';
  end if;

  select returned_at is not null into was_returned
    from class_submissions where assignment_id = p_assignment_id and student_id = p_student_id
    for update;
  was_returned := coalesce(was_returned, false);

  insert into class_submissions (classroom_id, assignment_id, student_id, user_id, book_id, book_title, book_snapshot)
    values (p_classroom_id, p_assignment_id, p_student_id, p_user_id, p_book_id, coalesce(p_book_title, ''), p_book_snapshot)
  on conflict (assignment_id, student_id) do update set
    book_id = excluded.book_id,
    book_title = excluded.book_title,
    book_snapshot = excluded.book_snapshot,
    user_id = excluded.user_id,
    version = class_submissions.version + 1,
    submitted_at = now(),
    returned_at = null
  returning id, version, submitted_at into r;
  return jsonb_build_object('id', r.id, 'version', r.version, 'submitted_at', r.submitted_at,
                            'was_returned', was_returned);
end $$;

revoke all on function public.school_valid_worksheet(jsonb) from public, anon, authenticated;
revoke all on function public.school_assignment_kind_locked() from public, anon, authenticated;
revoke all on function public.school_submit(uuid, uuid, uuid, uuid, text, text, jsonb) from public, anon, authenticated;
-- The worksheet check runs as whoever writes the row: only ever the
-- service role (or a definer RPC's owner).
grant execute on function public.school_valid_worksheet(jsonb) to service_role;
grant execute on function public.school_submit(uuid, uuid, uuid, uuid, text, text, jsonb) to service_role;


-- ════════ supabase-migrations/024_writing_year.sql ════════
-- Schools: "My Writing Year" — a per-child book built during the year — and
-- class printing (spec 2026-10-01 §3).
--
-- Same rules as 018–023: every table is read and written ONLY by api/ with
-- the service-role key. RLS is enabled with no policies, and the client
-- roles' table grants are revoked too, so the anon and authenticated keys
-- (which ship to browsers) can read nothing.
--
-- Deletion (lib/deleteUser.js order unchanged):
--   * writing_year_items / writing_year_meta cascade from classrooms and
--     class_students; a hand-in item also cascades from class_submissions.
--     So a child deleting their account mid-year (purgeUser deletes their
--     class_submissions, then the auth user, whose class_students row
--     cascades) takes every piece, their "About me" and the teacher's note
--     with them. A class purge (students first, then the classroom) does too.
--   * class_print_request_children cascades from class_students: a child who
--     leaves after a print request was made drops out of it (if it was not
--     yet sent to the printer). The request itself cascades from the
--     classroom; requested_by is ON DELETE SET NULL.
--   * The rendered PDFs live in the print-pdfs bucket under
--     writing-year/<child auth user id>/…; purgeUser removes that prefix.
--     They are also deleted 30 days after the box ships (purge cron).
--   None of these rows can block a purge: every FK cascades or sets null.
--
-- Apply BEFORE deploying the code that uses it. Idempotent: safe to re-run.

-- ── Pieces in a child's Writing Year ───────────────────────────────────
-- kind 'submission': a graded hand-in (book or worksheet). Its snapshot is
--   frozen when it is added (snapshot_version = the hand-in version then).
--   class_submissions keeps only the LATEST version's content, so at
--   preview/print time the book uses the hand-in's latest version if that
--   version is graded, else this frozen copy (the version the teacher chose),
--   else the latest (api/_writingYear.js).
-- kind 'book': one of the child's own books, frozen when suggested (a
--   data-URI-free copy, ≤ 200 KB — lib/school/snapshot.js).
-- A child's suggestion waits for the teacher (approved = false); a teacher's
-- own addition is approved from the start. Declining deletes the row.
create table if not exists public.writing_year_items (
  id uuid primary key default gen_random_uuid(),
  classroom_id uuid not null references public.classrooms(id) on delete cascade,
  student_id uuid not null references public.class_students(id) on delete cascade,
  kind text not null check (kind in ('submission','book')),
  submission_id uuid references public.class_submissions(id) on delete cascade,
  book_id text check (char_length(book_id) between 1 and 128),
  book_snapshot jsonb,
  snapshot_version int check (snapshot_version >= 1),
  title text not null default '' check (char_length(title) <= 200),
  position int not null check (position >= 1),
  added_by text not null check (added_by in ('teacher','child_suggested')),
  approved boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  check (
    (kind = 'submission' and submission_id is not null and book_id is null)
    or (kind = 'book' and submission_id is null and book_id is not null and jsonb_typeof(book_snapshot) = 'object')
  ),
  check (book_snapshot is null or (jsonb_typeof(book_snapshot) = 'object' and octet_length(book_snapshot::text) <= 250000)),
  -- Only a child's suggestion can be waiting.
  check (approved or added_by = 'child_suggested')
);
-- One row per piece per child (a teacher adding a suggested hand-in approves
-- the suggestion instead of duplicating it).
create unique index if not exists writing_year_items_sub_uniq
  on public.writing_year_items (student_id, submission_id) where submission_id is not null;
create unique index if not exists writing_year_items_book_uniq
  on public.writing_year_items (student_id, book_id) where book_id is not null;
-- The order of a child's book. Deferred, so a reorder can swap positions in
-- one transaction (school_wy_reorder).
do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'writing_year_items_position_uniq'
                 and conrelid = 'public.writing_year_items'::regclass) then
    alter table public.writing_year_items add constraint writing_year_items_position_uniq
      unique (student_id, position) deferrable initially deferred;
  end if;
end $$;
create index if not exists writing_year_items_class_idx on public.writing_year_items (classroom_id);
-- The class_submissions cascade.
create index if not exists writing_year_items_submission_idx
  on public.writing_year_items (submission_id) where submission_id is not null;
alter table public.writing_year_items enable row level security;
revoke all on public.writing_year_items from anon, authenticated;

-- ── "About me" (the child) and the teacher's note, one row per child ───
create table if not exists public.writing_year_meta (
  student_id uuid primary key references public.class_students(id) on delete cascade,
  classroom_id uuid not null references public.classrooms(id) on delete cascade,
  -- The three "About me" prompts: favorite thing to write about, my best
  -- sentence, what I learned. 200 each, 600 in all.
  about_favorite text not null default '' check (char_length(about_favorite) <= 200),
  about_best_sentence text not null default '' check (char_length(about_best_sentence) <= 200),
  about_learned text not null default '' check (char_length(about_learned) <= 200),
  teacher_note text not null default '' check (char_length(teacher_note) <= 600),
  cover_title text check (char_length(cover_title) between 1 and 60),
  updated_at timestamptz not null default now()
);
create index if not exists writing_year_meta_class_idx on public.writing_year_meta (classroom_id);
alter table public.writing_year_meta enable row level security;
revoke all on public.writing_year_meta from anon, authenticated;

-- ── Class print requests ───────────────────────────────────────────────
-- A teacher asks for the class's books (one softcover per child, included
-- in a paid license); the owner reviews it in the admin area and only then
-- sends it to Lulu as ONE print job with a line item per child, shipped to
-- the school in one box. Nothing here talks to Lulu by itself.
--   requested → approved → submitted → in_production → shipped
--   + canceled (owner or teacher, before submission) + failed (Lulu said no)
create table if not exists public.class_print_requests (
  id uuid primary key default gen_random_uuid(),
  classroom_id uuid not null references public.classrooms(id) on delete cascade,
  requested_by uuid references auth.users(id) on delete set null,
  -- R3: one printed copy per child per LICENSE TERM. The license and the
  -- start of its term when the teacher asked; one live request per term.
  -- (A license is purged only after its classes, so the cascade never
  -- outlives a request that still matters.)
  license_id uuid not null references public.class_licenses(id) on delete cascade,
  term_start timestamptz not null,
  -- '2026-27': printed on the cover only (Aug 1 boundary, lib/school/writingYear.js).
  school_year text not null check (school_year ~ '^[0-9]{4}-[0-9]{2}$'),
  status text not null default 'requested'
    check (status in ('requested','approved','submitted','in_production','shipped','canceled','failed')),
  school_name text not null check (char_length(school_name) between 1 and 120),
  contact_name text not null check (char_length(contact_name) between 1 and 80),
  contact_email text not null check (char_length(contact_email) between 3 and 254),
  contact_phone text not null check (char_length(contact_phone) between 5 and 30),
  address_line1 text not null check (char_length(address_line1) between 1 and 120),
  address_line2 text check (char_length(address_line2) <= 120),
  city text not null check (char_length(city) between 1 and 80),
  state_code text check (char_length(state_code) <= 10),
  postal_code text not null check (char_length(postal_code) between 1 and 20),
  country_code text not null check (country_code ~ '^[A-Z]{2}$'),
  children_count int not null check (children_count between 1 and 35),
  excluded_count int not null default 0 check (excluded_count >= 0),
  -- The children's books are written one by one after the request row
  -- (a class's worth is too big for one request body); set when all are in.
  -- Nothing can be approved before.
  books_frozen_at timestamptz,
  -- Chosen by the owner at approval from Lulu's shipping options.
  shipping_level text check (shipping_level in ('MAIL','PRIORITY_MAIL','GROUND_HD','GROUND_BUS','GROUND','EXPEDITED','EXPRESS')),
  -- Set once, atomically, by the one admin call that is allowed to create
  -- the Lulu print job (status approved + submit_claimed_at null → now()).
  -- A double click finds it set and never reaches Lulu. While it is set the
  -- request can't be canceled: Lulu may have the order. Only the owner's
  -- explicit reconcile (record the job id, or "checked Lulu — no order")
  -- clears it.
  submit_claimed_at timestamptz,
  lulu_print_job_id text,
  lulu_status text,
  tracking jsonb,
  error text check (char_length(error) <= 1000),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  approved_at timestamptz,
  submitted_at timestamptz,
  shipped_at timestamptz,
  canceled_at timestamptz,
  -- The rendered PDFs are deleted 30 days after shipping (api/cron/purge-deletions.js).
  pdfs_purged_at timestamptz
);
-- R3: one printed copy per child per license term — a second request in
-- the same term is refused while one is live (canceled frees the slot).
-- The index is the race-safe guard; api/ only pre-checks.
create unique index if not exists class_print_requests_live_uniq
  on public.class_print_requests (license_id, term_start) where status <> 'canceled';
create index if not exists class_print_requests_class_idx on public.class_print_requests (classroom_id, created_at desc);
create index if not exists class_print_requests_status_idx on public.class_print_requests (status, created_at desc);
create unique index if not exists class_print_requests_lulu_idx
  on public.class_print_requests (lulu_print_job_id) where lulu_print_job_id is not null;
alter table public.class_print_requests enable row level security;
revoke all on public.class_print_requests from anon, authenticated;

-- Each included child's book, frozen when the teacher asked: what gets
-- printed is what the teacher saw in the summary. The PDFs are rendered by
-- the admin step and stored under writing-year/<child auth user id>/.
create table if not exists public.class_print_request_children (
  id uuid primary key default gen_random_uuid(),
  request_id uuid not null references public.class_print_requests(id) on delete cascade,
  student_id uuid not null references public.class_students(id) on delete cascade,
  display_name text not null check (char_length(display_name) between 1 and 24),
  position int not null check (position >= 1),
  -- '{}' until api/ writes the frozen book (see books_frozen_at).
  book jsonb not null default '{}'::jsonb check (jsonb_typeof(book) = 'object' and octet_length(book::text) <= 2000000),
  interior_key text,
  cover_key text,
  page_count int check (page_count >= 1),
  rendered_at timestamptz,
  -- Set when the last render was refused because text didn't fit a page
  -- (lib/print/overflow.js), e.g. 'Text does not fit on page 7, 12'.
  render_problem text check (char_length(render_problem) <= 300),
  unique (request_id, student_id)
);
create index if not exists class_print_request_children_student_idx
  on public.class_print_request_children (student_id);
alter table public.class_print_request_children enable row level security;
revoke all on public.class_print_request_children from anon, authenticated;

-- ── RPCs (service role only) ────────────────────────────────────────────
-- Errors are raised with a bare message (SQLSTATE P0001); PostgREST returns
-- it as {code:'P0001', message:'<name>'} and api/ maps the name.

-- Add a piece to a child's Writing Year, at the end. Serialised per child by
-- an advisory lock, so two adds can't take the same position and the caps
-- hold under concurrency.
--   Teacher, a hand-in: p_submission_id. The hand-in must be in this class
--     and graded (any version). The child is taken from the hand-in. If the
--     child already suggested it, the suggestion is approved instead.
--   Child, a hand-in or a book: p_student_id + (p_submission_id | p_book_id
--     + p_book_snapshot). Their own hand-ins only (checked here); a book is
--     read by api/ from their own user_books row.
-- Returns {id, position, approved, existed}.
create or replace function public.school_wy_add_item(
  p_classroom_id uuid, p_student_id uuid, p_submission_id uuid,
  p_book_id text, p_book_snapshot jsonb, p_title text, p_added_by text,
  p_max_items int, p_max_pending int
)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  sid uuid := p_student_id;
  sub record;
  sub_title text := '';
  sub_snapshot jsonb;
  sub_version int;
  existing record;
  pos int;
  new_id uuid;
begin
  if p_submission_id is not null then
    select id, student_id, book_title, book_snapshot, version into sub from class_submissions
      where id = p_submission_id and classroom_id = p_classroom_id;
    if not found then raise exception 'submission_not_found'; end if;
    if sid is null then sid := sub.student_id; end if;
    if sub.student_id <> sid then raise exception 'submission_not_found'; end if;
    sub_title := coalesce(sub.book_title, '');
    -- Frozen now: the version on screen when it was chosen.
    if octet_length(sub.book_snapshot::text) <= 250000 then
      sub_snapshot := sub.book_snapshot;
      sub_version := sub.version;
    end if;
    if p_added_by = 'teacher'
       and not exists (select 1 from submission_grades where submission_id = p_submission_id) then
      raise exception 'not_graded';
    end if;
  end if;
  if sid is null then raise exception 'student_not_found'; end if;
  if not exists (select 1 from class_students where id = sid and classroom_id = p_classroom_id and status = 'active') then
    raise exception 'student_not_found';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('writing_year:' || sid::text, 0));

  select id, position, approved into existing from writing_year_items
    where student_id = sid
      and ((p_submission_id is not null and submission_id = p_submission_id)
        or (p_book_id is not null and book_id = p_book_id));
  if found then
    if p_added_by = 'teacher' and not existing.approved then
      -- Approving a child's suggestion freezes the version on screen now.
      update writing_year_items set approved = true, updated_at = now(),
        book_snapshot = case when p_submission_id is not null and sub_snapshot is not null then sub_snapshot else book_snapshot end,
        snapshot_version = case when p_submission_id is not null and sub_snapshot is not null then sub_version else snapshot_version end
        where id = existing.id;
      return jsonb_build_object('id', existing.id, 'position', existing.position, 'approved', true, 'existed', true);
    end if;
    return jsonb_build_object('id', existing.id, 'position', existing.position, 'approved', existing.approved, 'existed', true);
  end if;

  if (select count(*) from writing_year_items where student_id = sid) >= p_max_items then
    raise exception 'too_many_items';
  end if;
  if p_added_by = 'child_suggested'
     and (select count(*) from writing_year_items where student_id = sid and not approved) >= p_max_pending then
    raise exception 'too_many_pending';
  end if;

  select coalesce(max(position), 0) + 1 into pos from writing_year_items where student_id = sid;
  insert into writing_year_items (classroom_id, student_id, kind, submission_id, book_id, book_snapshot,
                                  snapshot_version, title, position, added_by, approved)
    values (p_classroom_id, sid,
            case when p_submission_id is not null then 'submission' else 'book' end,
            p_submission_id,
            case when p_submission_id is null then p_book_id end,
            case when p_submission_id is null then p_book_snapshot else sub_snapshot end,
            sub_version,
            left(coalesce(nullif(p_title, ''), sub_title), 200),
            pos, p_added_by, p_added_by = 'teacher')
    returning id into new_id;
  return jsonb_build_object('id', new_id, 'position', pos, 'approved', p_added_by = 'teacher', 'existed', false);
end $$;

-- Reorder one child's pieces: p_item_ids must be exactly that child's
-- pieces (every one, once), in the new order; positions become 1..n.
-- Same lock as school_wy_add_item, and the position constraint is deferred,
-- so the swap is one consistent write ('order_mismatch' otherwise).
create or replace function public.school_wy_reorder(p_classroom_id uuid, p_student_id uuid, p_item_ids uuid[])
returns int language plpgsql security definer set search_path = public as $$
declare
  n int;
begin
  perform pg_advisory_xact_lock(hashtextextended('writing_year:' || p_student_id::text, 0));
  select count(*) into n from writing_year_items
    where student_id = p_student_id and classroom_id = p_classroom_id;
  if n <> coalesce(array_length(p_item_ids, 1), 0)
     or n <> (select count(distinct x) from unnest(p_item_ids) x)
     or exists (select 1 from unnest(p_item_ids) x
                where not exists (select 1 from writing_year_items
                                  where id = x and student_id = p_student_id and classroom_id = p_classroom_id)) then
    raise exception 'order_mismatch';
  end if;
  update writing_year_items w set position = o.ord, updated_at = now()
    from unnest(p_item_ids) with ordinality as o(id, ord)
    where w.id = o.id;
  return n;
end $$;

-- Create a class print request and its children in one transaction. The
-- license is read here, under a share lock, so a lapse between api/'s check
-- and this write can't let it through (R1: active, grace or comped — never
-- a trial), and the request is tied to that license's current term: the
-- partial unique index refuses a second live request in the same term
-- ('already_requested', R3).
-- p_children: [{student_id, display_name}] in print order. Their books are
-- written by api/ right after (one row at a time), then books_frozen_at.
-- Returns {id, children_count, children: [{id, student_id}]}.
create or replace function public.school_create_class_print(
  p_classroom_id uuid, p_requested_by uuid, p_school_year text, p_address jsonb,
  p_children jsonb, p_excluded_count int
)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  lic record;
  req_id uuid;
  n int := coalesce(jsonb_array_length(p_children), 0);
begin
  select id, status, starts_at, expires_at into lic from class_licenses where classroom_id = p_classroom_id for share;
  if not found or lic.status not in ('active','grace','comped')
     or (lic.status <> 'grace' and lic.expires_at <= now()) then
    raise exception 'license_not_paid';
  end if;
  if n < 1 then raise exception 'no_children'; end if;

  begin
    insert into class_print_requests (classroom_id, requested_by, license_id, term_start, school_year, school_name, contact_name,
      contact_email, contact_phone, address_line1, address_line2, city, state_code, postal_code,
      country_code, children_count, excluded_count)
    values (p_classroom_id, p_requested_by, lic.id, lic.starts_at, p_school_year, p_address->>'school_name', p_address->>'contact_name',
      p_address->>'contact_email', p_address->>'contact_phone', p_address->>'address_line1',
      nullif(p_address->>'address_line2', ''), p_address->>'city', nullif(p_address->>'state_code', ''),
      p_address->>'postal_code', p_address->>'country_code', n, coalesce(p_excluded_count, 0))
    returning id into req_id;
  exception when unique_violation then
    raise exception 'already_requested';
  end;

  insert into class_print_request_children (request_id, student_id, display_name, position)
    select req_id, (c->>'student_id')::uuid, c->>'display_name', o.ord
      from jsonb_array_elements(p_children) with ordinality as o(c, ord)
      join class_students s on s.id = (c->>'student_id')::uuid
                           and s.classroom_id = p_classroom_id and s.status = 'active';
  get diagnostics n = row_count;
  if n <> jsonb_array_length(p_children) then raise exception 'children_changed'; end if;

  return jsonb_build_object('id', req_id, 'children_count', n,
    'children', (select jsonb_agg(jsonb_build_object('id', id, 'student_id', student_id) order by position)
                 from class_print_request_children where request_id = req_id));
end $$;

revoke all on function public.school_wy_add_item(uuid, uuid, uuid, text, jsonb, text, text, int, int) from public, anon, authenticated;
revoke all on function public.school_wy_reorder(uuid, uuid, uuid[]) from public, anon, authenticated;
revoke all on function public.school_create_class_print(uuid, uuid, text, jsonb, jsonb, int) from public, anon, authenticated;
grant execute on function public.school_wy_add_item(uuid, uuid, uuid, text, jsonb, text, text, int, int) to service_role;
grant execute on function public.school_wy_reorder(uuid, uuid, uuid[]) to service_role;
grant execute on function public.school_create_class_print(uuid, uuid, text, jsonb, jsonb, int) to service_role;


-- ════════ supabase-migrations/025_illustrations_no_listing.sql ════════
-- book-illustrations: no more bucket listing by anyone (privacy review
-- §4.2 / §7.7). ALREADY APPLIED IN PRODUCTION by the owner; this file
-- records exactly that change so the repo matches the database.
--
-- Migration 014 created "Illustrations are publicly readable", a SELECT
-- policy on storage.objects with no role restriction. A public bucket does
-- not need a SELECT policy for downloads (public URLs bypass RLS), so the
-- policy's only effect was to let the anon key call
-- POST /storage/v1/object/list/book-illustrations and enumerate every
-- user-id folder and file name.
--
-- Replaced with a policy that lets a signed-in user see (and so list) only
-- their own folder. Public URL downloads are unaffected: the PDF worker,
-- Lulu, the gallery and the apps keep fetching by URL with no session.
--
-- NOT done here: restricting direct client WRITES for student accounts.
-- The iOS app's drawing canvas (ios-native/MyBookLab/Services/
-- IllustrationUploader.swift, used by CreateBookView "Draw" and the avatar
-- editor) uploads straight into <user id>/ with the user's own session, and
-- it is available to class (student) accounts. Adding
-- `coalesce(auth.jwt()->'app_metadata'->>'role','') <> 'student'` to the
-- 014 insert/update policies would break drawing for students, so that
-- change waits for a server-side drawing upload (or a private
-- student-illustrations bucket with signed URLs).
--
-- Idempotent: safe to re-run.

drop policy if exists "Illustrations are publicly readable" on storage.objects;
drop policy if exists "Users read their own illustrations" on storage.objects;

create policy "Users read their own illustrations"
  on storage.objects for select
  to authenticated
  using (
    bucket_id = 'book-illustrations'
    and (storage.foldername(name))[1] = auth.uid()::text
  );


-- ════════ supabase-migrations/026_print_order_pdf_retention.sql ════════
-- Consumer printed-book PDFs: retention marker (privacy review §4.6 / §7.5).
--
-- api/print-orders/pdf-worker.js stores each order's PDFs in the private
-- print-pdfs bucket as <order id>/{interior,cover}.pdf. Until now nothing
-- ever deleted them. Two paths now do:
--   * lib/deleteUser.js purgeUser deletes every order's folder BEFORE the
--     auth delete (print_orders.user_id cascades, so the ids die with it);
--   * api/cron/retention.js (lib/print/orderRetention.js) deletes them 90
--     days after the order shipped/was delivered, or 30 days after it was
--     refunded or failed or was left in pending/paid/pdf_ready, and stamps
--     this column.
--
-- Apply BEFORE deploying the code that uses it. Idempotent.

alter table public.print_orders
  add column if not exists pdfs_purged_at timestamptz;

-- The nightly job's lookup: final orders not yet purged, oldest first.
create index if not exists idx_print_orders_pdf_retention
  on public.print_orders (updated_at)
  where pdfs_purged_at is null;


-- ════════ supabase-migrations/027_vendor_deletion_queue.sql ════════
-- Vendor-side deletion retries (privacy review §4.6 / §7.23).
--
-- lib/deleteUser.js purgeUser deletes the account's Stripe Customer and
-- RevenueCat subscriber (lib/vendorDeletion.js). A failed call never blocks
-- the purge; it lands here and api/cron/retention.js retries it nightly,
-- deleting the row on success. After 8 attempts a row stays for a human.
--
-- external_id is the vendor's own id only: a Stripe customer id (cus_…) or
-- the RevenueCat app_user_id (the deleted Supabase user's UUID). No names,
-- no emails. Deliberately no FK to auth.users: the account is gone.
--
-- Service role only: RLS on, no policies, client grants revoked.
-- Apply BEFORE deploying the code that uses it. Idempotent.

create table if not exists public.vendor_deletion_queue (
  id bigint generated always as identity primary key,
  vendor text not null check (vendor in ('stripe','revenuecat')),
  external_id text not null check (char_length(external_id) between 1 and 255),
  attempts int not null default 1 check (attempts >= 0),
  last_status int,
  last_attempt_at timestamptz not null default now(),
  created_at timestamptz not null default now(),
  unique (vendor, external_id)
);
alter table public.vendor_deletion_queue enable row level security;
revoke all on public.vendor_deletion_queue from anon, authenticated;


-- ════════ supabase-migrations/028_retention_and_deletion_log.sql ════════
-- Data lifecycle: retention jobs, license-lapse purge, teacher deletes and
-- the deletion evidence log (privacy review §4.7 / §7.1, 7.2, 7.3, 7.22).
--
-- * deletion_log — one row per deletion of school data (teacher "delete
--   now" of a student or a class, the nightly purge of removed students and
--   of classes 90 days after their license lapsed). Ids, action, actor and
--   row counts only; never a name or content. It is the evidence an NDPA
--   Exhibit D disposal certificate is written from, so it deliberately has
--   no FKs (the things it describes are gone) and is never purged by the
--   jobs it records. Written by lib/school/deletionLog.js. A class purge
--   also writes one 'purge_class_student' row per child; a teacher account
--   purge writes 'purge_teacher_class' per class. status 'partial' = a class
--   delete that stopped part-way; api/cron/retention.js resumes it.
-- * class_licenses.purge_warning_30_at / purge_warning_7_at — when the
--   teacher was emailed "this class will be deleted in 30 / 7 days".
--   Migration 031 clears them whenever the status or expiry changes, so a
--   renewed and re-lapsed license is warned again (lib/school/lifecycle.js).
-- * Indexes for the nightly deletes by age (api/cron/retention.js).
--
-- Service role only: RLS on, no policies, client grants revoked.
-- Apply BEFORE deploying the code that uses it. Idempotent.

create table if not exists public.deletion_log (
  id bigint generated always as identity primary key,
  actor_user_id uuid,
  actor_kind text not null check (actor_kind in ('teacher','system')),
  action text not null check (action in (
    'delete_student','delete_class','purge_removed_student','purge_lapsed_class',
    'purge_teacher_class','purge_class_student','legacy_sunset'
  )),
  classroom_id uuid,
  target_id uuid,
  counts jsonb not null default '{}'::jsonb,
  reason text check (char_length(reason) <= 200),
  status text not null default 'started' check (status in ('started','done','partial','failed','dry_run')),
  created_at timestamptz not null default now(),
  completed_at timestamptz
);
create index if not exists deletion_log_class_idx on public.deletion_log (classroom_id, created_at desc);
create index if not exists deletion_log_resume_idx on public.deletion_log (status, created_at) where status in ('started','partial');
create index if not exists deletion_log_actor_idx on public.deletion_log (actor_user_id, created_at desc);
alter table public.deletion_log enable row level security;
revoke all on public.deletion_log from anon, authenticated;

alter table public.class_licenses
  add column if not exists purge_warning_30_at timestamptz,
  add column if not exists purge_warning_7_at timestamptz;

-- Nightly deletes by age.
create index if not exists class_checkins_created_idx on public.class_checkins (created_at);
create index if not exists ssia_created_idx on public.student_sign_in_attempts (created_at);
create index if not exists class_students_removed_idx on public.class_students (removed_at) where status = 'removed';
create index if not exists submissions_legacy_anon_idx on public.submissions (submitted_at) where user_id is null;


-- ════════ supabase-migrations/029_published_books_visibility.sql ════════
-- published_books: hidden books and author account ids stay private
-- (privacy review §4.2 / §7.8).
--
-- 001 created "Published books are publicly readable" USING (true), so the
-- anon key could read every row straight from PostgREST — reported books
-- that were auto-hidden (016) included — with user_id, the author's
-- account UUID (often a child's).
--
-- No client reads this table directly: the web app and the iOS app both go
-- through api/publish-book.js (service role), which now returns is_owner
-- and an opaque author handle instead of user_id (lib/authorRef.js), and
-- api/report-book.js resolves that handle for "block this author". So:
--   * the read policy only shows visible books;
--   * anon/authenticated lose SELECT on user_id (and on the moderation
--     columns), keeping column-level SELECT on the public ones. A
--     column-level REVOKE does nothing while a table-level grant exists,
--     hence revoke-all-then-grant-columns.
-- The service role (API) is unaffected.
--
-- Deploy the API change first or together; this only removes access no
-- shipped client uses. Idempotent.

drop policy if exists "Published books are publicly readable" on public.published_books;
drop policy if exists "Visible published books are publicly readable" on public.published_books;
create policy "Visible published books are publicly readable"
  on public.published_books for select
  using (hidden = false);

revoke select on public.published_books from anon, authenticated;
grant select (
  id, slug, title, author_name, author_age, cover_emoji, cover_color,
  book_data, reaction_counts, featured, featured_at, published_at, created_at
) on public.published_books to anon, authenticated;


-- ════════ supabase-migrations/030_checkins_toggle.sql ════════
-- Per-class switch for student check-ins (privacy review §7.28): a school
-- or district can turn feelings collection off (PPRA / district
-- preference). Default ON keeps today's behaviour.
--
-- When off: POST /api/school/checkin refuses (403 checkins_off) and stores
-- nothing; the child's app hides the check-in entry (it reads the flag
-- from GET /api/school/assignments). Existing check-ins are not deleted by
-- the switch; they age out with the 30-day retention (api/cron/retention.js).
--
-- Apply BEFORE deploying the code that reads it (classes list, student
-- routes select it). Idempotent.

alter table public.classrooms
  add column if not exists checkins_enabled boolean not null default true;


-- ════════ supabase-migrations/031_license_status_changed_at.sql ════════
-- License lifecycle dating (review fix I3/I4, lib/school/lifecycle.js).
--
-- * status_changed_at: when the license last changed status. A lapsed or
--   canceled license is dated from this, not from updated_at (which moves
--   on any edit, e.g. images_used). Existing rows start at now(), so no
--   license already lapsed/canceled can be purged sooner than 90 days after
--   this migration — and only after the full 30 + 7 day warning schedule.
-- * The lapse warnings (028) are cleared whenever the status or the expiry
--   changes: a renewal (or any re-lapse) restarts the schedule from zero,
--   and the nightly query can select "needs a warning" with plain
--   IS NULL filters.
-- * Indexes for the nightly selection.
--
-- Apply BEFORE deploying the code that uses it. Idempotent.

alter table public.class_licenses
  add column if not exists status_changed_at timestamptz not null default now();

create or replace function public.class_licenses_lifecycle_stamps()
returns trigger
language plpgsql
set search_path = public
as $$
begin
  if new.status is distinct from old.status then
    new.status_changed_at := now();
  end if;
  if new.status is distinct from old.status or new.expires_at is distinct from old.expires_at then
    new.purge_warning_30_at := null;
    new.purge_warning_7_at := null;
  end if;
  return new;
end;
$$;

revoke all on function public.class_licenses_lifecycle_stamps() from public, anon, authenticated;

drop trigger if exists class_licenses_lifecycle_stamps on public.class_licenses;
create trigger class_licenses_lifecycle_stamps
  before update on public.class_licenses
  for each row execute function public.class_licenses_lifecycle_stamps();

create index if not exists class_licenses_ended_idx
  on public.class_licenses (status_changed_at)
  where classroom_id is not null and status in ('lapsed','canceled');
create index if not exists class_licenses_expiring_idx
  on public.class_licenses (expires_at)
  where classroom_id is not null and status in ('trial','active','pending_payment');


-- ════════ supabase-migrations/032_admin_access_log.sql ════════
-- Hardening sprint B: owner/admin access log (privacy review §4.11, §7 item 16).
--
-- Every use of an OWNER_USER_ID-gated endpoint (api/admin/*) writes one row:
-- who, what, which record, why, when. It is the evidence that access to
-- student records (e.g. a child's Writing Year PDF during print QA) was
-- deliberate and bounded — SOC 2 CC6/CC7, NDPA Article V.
--
-- Same rules as 018–024: written and read ONLY by api/ with the service-role
-- key. RLS is on with no policies and the client roles' grants are revoked,
-- so the anon and authenticated keys (which ship to browsers) can read
-- nothing.
--
-- `actor` deliberately has NO foreign key to auth.users: the log must
-- outlive the account that wrote it (an owner account deletion must not
-- erase the record of what that account looked at).
--
-- `detail` carries ids and counts only — never a child's name, text or
-- feelings.
--
-- Apply BEFORE deploying the code that writes it (the writes are best-effort
-- for read actions and fail-closed for the bulk picture reset, see
-- api/_adminLog.js). Idempotent: safe to re-run.

create table if not exists public.admin_access_log (
  id bigint generated always as identity primary key,
  actor uuid not null,
  action text not null check (char_length(action) between 1 and 80),
  target_table text check (target_table is null or char_length(target_table) <= 80),
  target_id text check (target_id is null or char_length(target_id) <= 200),
  reason text check (reason is null or char_length(reason) <= 500),
  detail jsonb not null default '{}'::jsonb,
  at timestamptz not null default now()
);
create index if not exists admin_access_log_at_idx on public.admin_access_log (at desc);
create index if not exists admin_access_log_target_idx on public.admin_access_log (target_table, target_id);

alter table public.admin_access_log enable row level security;
revoke all on public.admin_access_log from anon, authenticated;

-- Append-only in practice: the API only ever INSERTs and SELECTs. (The
-- service role bypasses RLS and grants; a trigger forbidding UPDATE/DELETE
-- would also block legitimate retention pruning, so it is a policy, not a
-- constraint. Retention: keep at least 1 year — see the IR runbook.)
comment on table public.admin_access_log is
  'Owner/admin access to user and student records. Service-role only. Insert-only by convention; keep >= 1 year.';


-- ════════ supabase-migrations/033_refund_image.sql ════════
-- Hardening sprint B review fix I4: give a picture back when it was
-- generated (and metered) but then REFUSED because output moderation was
-- down and the caller fails closed (students; teacher-made student
-- avatars). The child/class must not lose an allowance for a picture they
-- never received.
--
-- Mirrors school_bump_image (018): undoes one tick of the student's
-- images_today (only if it was taken today) and one of the class license's
-- images_used. Never goes below zero. Service role only.
--
-- Write-only here: NOT applied. Apply after 032. Idempotent: safe to re-run.
-- Until it is applied the API's refund call fails (404) and is logged; the
-- refusal itself still works.

create or replace function public.school_refund_image(p_student_id uuid)
returns boolean language plpgsql security definer set search_path = public as $$
declare
  st record;
begin
  select id, classroom_id, images_day, images_today into st
    from class_students where id = p_student_id for update;
  if not found then return false; end if;
  if st.images_day is distinct from current_date or st.images_today <= 0 then return false; end if;

  update class_students set images_today = images_today - 1 where id = st.id;
  update class_licenses set images_used = greatest(images_used - 1, 0), updated_at = now()
    where classroom_id = st.classroom_id;
  return true;
end $$;

revoke all on function public.school_refund_image(uuid) from public, anon, authenticated;
grant execute on function public.school_refund_image(uuid) to service_role;


-- ════════ supabase-migrations/034_school_billing.sql ════════
-- Stage 4: teacher verification, per-seat pricing, Stripe purchase,
-- school plans, seat blocks, renewals.
--
-- Spec: docs/superpowers/specs/2026-10-01-worksheets-grading-yearbook-design.md §4,
-- docs/superpowers/notes/stage4-license-terms.md (starts_at rules),
-- docs/superpowers/specs/2026-09-26-schools-design.md §6 (billing).
--
-- Same rules as 018–033: every table here is written and read ONLY by api/
-- with the service-role key. RLS is enabled with NO policies and the client
-- roles' grants are revoked, so the anon and authenticated keys (which ship
-- to browsers) can read nothing.
--
-- Write-only here: NOT applied. Apply after 033 and BEFORE deploying the
-- Stage 4 code. Additive with defaults, so the previous code keeps working.
-- Idempotent: safe to re-run.

-- ── 1. Teacher verification ─────────────────────────────────────────────
-- A teacher is verified when app_metadata.teacher_verified_at is set
-- (requireVerifiedTeacher in api/_school.js). It is set automatically for a
-- confirmed school-domain email, or by the owner from this queue.
create table if not exists public.teacher_verification_requests (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  -- Only the DOMAIN of the teacher's email, never the address: the owner
  -- alert and the queue carry domain + user id only.
  email_domain text not null check (char_length(email_domain) between 1 and 253),
  -- Optional, teacher-typed. Helps the owner look the school up.
  school_name text check (school_name is null or char_length(school_name) <= 120),
  status text not null default 'pending' check (status in ('pending','approved','declined')),
  decided_by uuid,
  decided_at timestamptz,
  decline_reason text check (decline_reason is null or char_length(decline_reason) <= 500),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create unique index if not exists teacher_verification_one_pending
  on public.teacher_verification_requests (user_id) where status = 'pending';
create index if not exists teacher_verification_queue_idx
  on public.teacher_verification_requests (status, created_at);
alter table public.teacher_verification_requests enable row level security;
revoke all on public.teacher_verification_requests from anon, authenticated;

-- Grandfather: every CURRENT class owner (and license owner) is verified, so
-- no existing class stops working — including the owner's own. Students are
-- never marked (they never own classes, but be explicit). Rows that already
-- carry teacher_verified_at are left alone, so a re-run changes nothing.
-- classrooms.owner_user_id may be NULL on very old legacy rows: EXISTS
-- simply never matches those.
update auth.users u
   set raw_app_meta_data = coalesce(u.raw_app_meta_data, '{}'::jsonb)
         || jsonb_build_object('teacher_verified_at', now(), 'teacher_verified_by', 'grandfathered')
 where coalesce(u.raw_app_meta_data->>'teacher_verified_at', '') = ''
   and coalesce(u.raw_app_meta_data->>'role', '') <> 'student'
   and (exists (select 1 from public.classrooms c where c.owner_user_id = u.id)
        or exists (select 1 from public.class_licenses l where l.owner_user_id = u.id));

-- ── 2. School plans (one invoice, many classes) ─────────────────────────
create table if not exists public.school_plans (
  id uuid primary key default gen_random_uuid(),
  -- The school admin: a verified teacher who bought the plan.
  owner_user_id uuid not null references auth.users(id) on delete restrict,
  school_name text not null check (char_length(school_name) between 1 and 120),
  status text not null check (status in ('pending_payment','active','grace','lapsed','canceled')),
  billing_method text not null check (billing_method in ('card','invoice','manual')),
  -- The 150 minimum is enforced by the API (lib/school/pricing.js); a
  -- manual/comped plan set by the owner may be smaller.
  seats int not null check (seats between 1 and 100000),
  -- A reduction waits for the renewal (never below the seats in use).
  pending_seats int check (pending_seats is null or pending_seats between 1 and 100000),
  price_tier text check (price_tier in ('standard','founding','school')),
  starts_at timestamptz not null default now(),
  expires_at timestamptz not null,
  stripe_customer_id text,
  stripe_subscription_id text,
  stripe_price_id text,
  -- The Stripe current_period_start of the last PAID period. starts_at moves
  -- only when a newly paid period's start is later than this.
  stripe_period_start timestamptz,
  -- created time of the last applied customer.subscription.* event, so an
  -- older event arriving late can't undo a newer one.
  stripe_event_at timestamptz,
  cancel_at_period_end boolean not null default false,
  dpa_version text,
  dpa_accepted_at timestamptz,
  dpa_accepted_by uuid,
  status_changed_at timestamptz not null default now(),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create unique index if not exists school_plans_subscription_uniq
  on public.school_plans (stripe_subscription_id) where stripe_subscription_id is not null;
create index if not exists school_plans_owner_idx on public.school_plans (owner_user_id);
alter table public.school_plans enable row level security;
revoke all on public.school_plans from anon, authenticated;

create or replace function public.school_plans_status_stamp()
returns trigger language plpgsql set search_path = public as $$
begin
  if new.status is distinct from old.status then new.status_changed_at := now(); end if;
  return new;
end $$;
revoke all on function public.school_plans_status_stamp() from public, anon, authenticated;
drop trigger if exists school_plans_status_stamp on public.school_plans;
create trigger school_plans_status_stamp before update on public.school_plans
  for each row execute function public.school_plans_status_stamp();

-- ── 3. Class licenses: billing columns ──────────────────────────────────
alter table public.class_licenses
  add column if not exists school_plan_id uuid references public.school_plans(id) on delete set null,
  add column if not exists price_tier text check (price_tier is null or price_tier in ('standard','founding','school')),
  add column if not exists pending_seats int check (pending_seats is null or pending_seats between 1 and 35),
  add column if not exists stripe_period_start timestamptz,
  add column if not exists stripe_event_at timestamptz,
  add column if not exists cancel_at_period_end boolean not null default false;
create unique index if not exists class_licenses_subscription_uniq
  on public.class_licenses (stripe_subscription_id) where stripe_subscription_id is not null and school_plan_id is null;
create index if not exists class_licenses_plan_idx on public.class_licenses (school_plan_id) where school_plan_id is not null;
create index if not exists class_licenses_grace_idx on public.class_licenses (expires_at) where status = 'grace';

-- ── 4. Seat offers: a school admin gives a block to a colleague's class ──
-- v1 transfer: the admin enters the colleague's class code and a seat
-- count; the colleague (the class owner, verified) accepts in their Plan &
-- billing panel. Nothing moves until they accept.
create table if not exists public.school_seat_offers (
  id uuid primary key default gen_random_uuid(),
  plan_id uuid not null references public.school_plans(id) on delete cascade,
  classroom_id uuid not null references public.classrooms(id) on delete cascade,
  seats int not null check (seats between 1 and 35),
  status text not null default 'pending' check (status in ('pending','accepted','declined','canceled')),
  created_by uuid not null,
  decided_by uuid,
  created_at timestamptz not null default now(),
  decided_at timestamptz
);
create unique index if not exists school_seat_offers_one_pending
  on public.school_seat_offers (plan_id, classroom_id) where status = 'pending';
create index if not exists school_seat_offers_class_idx on public.school_seat_offers (classroom_id) where status = 'pending';
alter table public.school_seat_offers enable row level security;
revoke all on public.school_seat_offers from anon, authenticated;

-- ── 5. Stripe event ledger (school billing) ─────────────────────────────
-- Claimed before an event is applied; a duplicate delivery finds its id and
-- is a no-op. If applying fails, the API deletes the claim and answers 500
-- so Stripe retries. Ordering is NOT by arrival: see lib/school/billingState.js.
create table if not exists public.stripe_school_events (
  event_id text primary key check (char_length(event_id) between 1 and 255),
  type text not null,
  object_id text,
  received_at timestamptz not null default now()
);
alter table public.stripe_school_events enable row level security;
revoke all on public.stripe_school_events from anon, authenticated;

-- ── 6. Seat-block assignment (atomic) ───────────────────────────────────
-- Gives (or resizes) a class's block from a school plan. Locks the plan row
-- so two parallel assignments can't oversell it. Rules:
--   * the plan is usable (pending_payment / active / grace) and not expired
--     (grace is usable until the nightly job ends it);
--   * 1..35 seats, never below the class's active students;
--   * the class has no license, or a trial / lapsed / canceled one, or is
--     already on THIS plan (resize). A class on its own card license, a
--     comp, or another plan is refused (cancel that first).
--   * the plan's blocks never sum past plan.seats.
-- The license mirrors the plan: status, expiry and term (starts_at). A trial
-- becoming a block starts the plan's current term: it can print once.
-- Returns {ok, license_id} or {error: code}.
create or replace function public.school_plan_assign(p_plan_id uuid, p_classroom_id uuid, p_seats int, p_owner uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  pl record;
  lic record;
  used int;
  enrolled int;
  lid uuid;
  has_lic boolean;
begin
  if p_seats is null or p_seats < 1 or p_seats > 35 then return jsonb_build_object('error', 'bad_seats'); end if;
  select * into pl from school_plans where id = p_plan_id for update;
  if not found then return jsonb_build_object('error', 'plan_not_found'); end if;
  if pl.status not in ('pending_payment','active','grace')
     or (pl.status <> 'grace' and pl.expires_at <= now()) then
    return jsonb_build_object('error', 'plan_not_active');
  end if;

  select count(*) into enrolled from class_students where classroom_id = p_classroom_id and status = 'active';
  if enrolled > p_seats then return jsonb_build_object('error', 'below_enrolled', 'enrolled', enrolled); end if;

  select * into lic from class_licenses where classroom_id = p_classroom_id for update;
  -- Captured now: the SELECT INTO below resets FOUND.
  has_lic := found;
  if has_lic and lic.school_plan_id is distinct from p_plan_id
     and lic.status not in ('trial','lapsed','canceled') then
    return jsonb_build_object('error', 'class_has_license');
  end if;

  select coalesce(sum(seats), 0) into used from class_licenses
    where school_plan_id = p_plan_id and classroom_id is distinct from p_classroom_id;
  if used + p_seats > pl.seats then
    return jsonb_build_object('error', 'plan_full', 'available', greatest(pl.seats - used, 0));
  end if;

  if has_lic then
    update class_licenses set
      school_plan_id = p_plan_id,
      status = pl.status,
      billing_method = pl.billing_method,
      price_tier = pl.price_tier,
      seats = p_seats,
      pending_seats = null,
      image_allowance = 300 * p_seats,
      -- A new block (from trial/lapsed) starts the plan's term with a fresh
      -- picture allowance; a resize on the same plan keeps both.
      images_used = case when lic.school_plan_id = p_plan_id then images_used else 0 end,
      starts_at = pl.starts_at,
      expires_at = pl.expires_at,
      stripe_customer_id = pl.stripe_customer_id,
      stripe_subscription_id = pl.stripe_subscription_id,
      stripe_price_id = pl.stripe_price_id,
      stripe_period_start = pl.stripe_period_start,
      school_name = pl.school_name,
      dpa_version = pl.dpa_version, dpa_accepted_at = pl.dpa_accepted_at, dpa_accepted_by = pl.dpa_accepted_by,
      updated_at = now()
      where id = lic.id
      returning id into lid;
  else
    insert into class_licenses (owner_user_id, classroom_id, origin, status, billing_method, price_tier, seats,
        image_allowance, images_used, starts_at, expires_at, school_plan_id, stripe_customer_id,
        stripe_subscription_id, stripe_price_id, stripe_period_start, school_name, dpa_version, dpa_accepted_at, dpa_accepted_by)
      values (p_owner, p_classroom_id, 'purchase', pl.status, pl.billing_method, pl.price_tier, p_seats,
        300 * p_seats, 0, pl.starts_at, pl.expires_at, p_plan_id, pl.stripe_customer_id,
        pl.stripe_subscription_id, pl.stripe_price_id, pl.stripe_period_start, pl.school_name, pl.dpa_version, pl.dpa_accepted_at, pl.dpa_accepted_by)
      returning id into lid;
  end if;
  return jsonb_build_object('ok', true, 'license_id', lid);
end $$;
revoke all on function public.school_plan_assign(uuid, uuid, int, uuid) from public, anon, authenticated;
grant execute on function public.school_plan_assign(uuid, uuid, int, uuid) to service_role;

-- ── 7. Pictures: pending_payment is usable (invoice billing, 30 days) ────
-- Same as 018's school_bump_image, plus 'pending_payment' (an invoice-billed
-- plan is usable while the invoice is open; expires_at = the due date).
-- Printing still needs a PAID term (school_create_class_print, 024).
create or replace function public.school_bump_image(p_student_id uuid, p_daily_limit int)
returns boolean language plpgsql security definer set search_path = public as $$
declare
  st record;
  lic record;
  archived timestamptz;
begin
  select id, classroom_id, images_day, images_today into st
    from class_students where id = p_student_id and status = 'active' for update;
  if not found then return false; end if;

  select archived_at into archived from classrooms where id = st.classroom_id;
  if archived is not null then return false; end if;

  select id, status, expires_at, image_allowance, images_used into lic
    from class_licenses where classroom_id = st.classroom_id for update;
  if not found then return false; end if;
  if lic.status not in ('trial','pending_payment','active','grace','comped') then return false; end if;
  if lic.status <> 'grace' and lic.expires_at <= now() then return false; end if;
  if lic.images_used >= lic.image_allowance then return false; end if;

  if st.images_day is distinct from current_date then
    st.images_today := 0;
  end if;
  if st.images_today >= p_daily_limit then return false; end if;

  update class_licenses set images_used = images_used + 1, updated_at = now() where id = lic.id;
  update class_students set images_day = current_date, images_today = st.images_today + 1 where id = st.id;
  return true;
end $$;
revoke all on function public.school_bump_image(uuid, int) from public, anon, authenticated;
grant execute on function public.school_bump_image(uuid, int) to service_role;
